(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,27471,e=>{e.v([])},60465,e=>{e.v(JSON.parse('[{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 01","metin":"Which of the following terms is formally defined as an \\"external computer add-on, such as a printer or a scanner; also known as an accessory\\"?","secenekler":["component","peripheral","motherboard","application","database"],"dogruCevap":1,"explanation":"Doğru cevap peripheral (çevre birimi) terimidir. Soru kökündeki \'external computer add-on\' (harici bilgisayar eklentisi) ve \'accessory\' (aksesuar) ifadeleri doğrudan çevre birimlerini niteleyen ayırt edici tetikleyici kavramlardır.","wrongExplanations":{"0":"Component (bileşen); anakart veya dahili sabit sürücü gibi bilgisayar kasasının içinde yer alan dahili (internal) donanım parçalarını tanımlar.","2":"Motherboard (anakart); bilgisayarın temel dahili bileşenidir, harici bir çevre birimi eklentisi değildir.","3":"Application (uygulama); kullanıcının belirli görevleri gerçekleştirmesini sağlayan bir yazılım türüdür.","4":"Database (veritabanı); verilerin organize biçimde saklandığı elektronik bilgi koleksiyonudur."},"vurgulu":true},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 02","metin":"Which of the following terms describes \\"any device internal to the computer, such as a primary hard disk drive or motherboard\\"?","secenekler":["peripheral","software","network","component","database"],"dogruCevap":3,"explanation":"Doğru cevap component (bileşen) terimidir. Soru metninde geçen \'internal to the computer\' (bilgisayar kasasının içinde yer alan) ifadesi ile \'motherboard\' ve \'primary hard disk drive\' örnekleri doğrudan dahili bileşenleri işaret eder.","wrongExplanations":{"0":"Peripheral (çevre birimi); bilgisayar kasasının dışında yer alan harici eklentileri (yazıcı, tarayıcı vb.) ifade eder.","1":"Software (yazılım); donanım üzerinde çalışan program kodlarını ve yönergeleri tanımlar, fiziksel dahili aygıt değildir.","2":"Network (ağ); kaynak paylaşımı amacıyla birbirine bağlanmış bilgisayarlar grubudur.","4":"Database (veritabanı); bilgilerin organize edilmiş biçimde saklandığı dijital veri tabanıdır."},"vurgulu":true},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 03","metin":"Which IT term literally means \\"that which is given\\" and refers to \\"raw information of any kind\\"?","secenekler":["data","code","file","disk","host"],"dogruCevap":0,"explanation":"Doğru cevap data (veri) terimidir. Terimin kökenindeki \'that which is given\' (verilen şey) anlamı ve \'raw information of any kind\' (her türlü işlenmemiş ham bilgi) resmi tanımı doğrudan veriyi ifade eder.","wrongExplanations":{"1":"Code (kod); bir programı oluşturan programlama dili komutlarıdır, ham bilginin kökensel tanımı değildir.","2":"File (dosya); verilerin depolama birimlerinde kaydedildiği organize bilgi bloklarıdır.","3":"Disk (disk); verilerin manyetik veya optik olarak depolandığı fiziksel saklama ortamıdır.","4":"Host (ana bilgisayar); ağ üzerinde diğer cihazlara hizmet veya kaynak sağlayan bilgisayardır."},"vurgulu":false},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 04","metin":"Which of the following is formally defined as an \\"organized, electronic collection of information optimized for fast access and typically consisting of rows, columns, indexes, and keys\\"?","secenekler":["peripheral","network","database","software","hardware"],"dogruCevap":2,"explanation":"Doğru cevap database (veritabanı) terimidir. \'Organized, electronic collection of information\' ve özellikle \'rows, columns, indexes, and keys\' (satırlar, sütunlar, indeksler ve anahtarlar) ifadeleri veritabanı yapısının kesin tetikleyicileridir.","wrongExplanations":{"0":"Peripheral (çevre birimi); harici donanım aksesuarlarını ifade eder, veri koleksiyonu değildir.","1":"Network (ağ); kaynak paylaşmak üzere birbirine bağlanan bilgisayarlar topluluğudur.","3":"Software (yazılım); bilgisayarda çalışmak üzere tasarlanan programların genel adıdır.","4":"Hardware (donanım); bilgisayarı oluşturan tüm fiziksel parçaların üst kategorisidir."},"vurgulu":false},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 05","metin":"Which technical term denotes \\"a software program which allows a user to perform specific tasks such as word processing, email, accounting, database management\\"?","secenekler":["hardware","database","network","component","application"],"dogruCevap":4,"explanation":"Doğru cevap application (uygulama) kavramıdır. Tanımdaki \'a software program\' ifadesi ve kullanıcının \'specific tasks\' (kelime işlem, e-posta, muhasebe gibi belirli görevler) yürütmesini sağlaması application teriminin temel özelliğidir.","wrongExplanations":{"0":"Hardware (donanım); bilgisayarın fiziksel ve somut tüm parçalarını kapsayan genel addır.","1":"Database (veritabanı); verilerin depolandığı ve organize edildiği bilgi koleksiyonudur.","2":"Network (ağ); bilgisayarlar arasındaki kaynak paylaşımını sağlayan bağlantı altyapısıdır.","3":"Component (bileşen); bilgisayar kasasının içinde yer alan donanım birimidir."},"vurgulu":true},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 06","metin":"Which of the following terms encompasses all \\"physical things that make up a computer, such as a component or a peripheral\\"?","secenekler":["hardware","software","database","Internet","firmware"],"dogruCevap":0,"explanation":"Doğru cevap hardware (donanım) terimidir. Bilgisayarı oluşturan dahili bileşenleri (component) ve harici çevre birimlerini (peripheral) kapsayan \'physical things that make up a computer\' ifadesi donanımın standart teknik tanımıdır.","wrongExplanations":{"1":"Software (yazılım); donanım üzerinde çalışan fiziksel olmayan program kodları ve yönergelerdir.","2":"Database (veritabanı); organize elektronik verilerin tutulduğu mantıksal yapıdır.","3":"Internet (İnternet); dünya genelindeki bilgisayarları birbirine bağlayan küresel ağ altyapısıdır.","4":"Firmware (bellenim); donanımların düşük seviyeli denetimini sağlayan salt okunur yazılımdır."},"vurgulu":true},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 07","metin":"Which general IT concept is formally defined as \\"any program designed to run on a computer\\"?","secenekler":["hardware","software","peripheral","component","processor"],"dogruCevap":1,"explanation":"Doğru cevap software (yazılım) kavramıdır. \'Any program designed to run on a computer\' (bir bilgisayarda çalışmak üzere tasarlanmış herhangi bir program) tanımı yazılımın en temel ve kapsayıcı tanımıdır.","wrongExplanations":{"0":"Hardware (donanım); bilgisayarın elle tutulur tüm fiziksel parçalarını ifade eder.","2":"Peripheral (çevre birimi); sisteme sonradan dışarıdan bağlanan yazıcı veya tarayıcı gibi aksesuarlardır.","3":"Component (bileşen); anakart veya dahili sabit sürücü gibi kasa içi donanım birimleridir.","4":"Processor (işlemci); komutları işleyen temel dahili donanım bileşenidir."},"vurgulu":true},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 08","metin":"Which networking term represents \\"a group of connected computers which share resources\\"?","secenekler":["database","software","hardware","computer","network"],"dogruCevap":4,"explanation":"Doğru cevap network (ağ) terimidir. \'A group of connected computers which share resources\' (kaynak paylaşan birbirine bağlı bilgisayarlar grubu) ifadesi bilgisayar ağlarının standart teknik tanımıdır.","wrongExplanations":{"0":"Database (veritabanı); verilerin depolandığı ve yönetildiği elektronik koleksiyondur.","1":"Software (yazılım); bilgisayarda çalışan programlar ve uygulamalar bütünüdür.","2":"Hardware (donanım); fiziksel elektronik ve mekanik aygıtların bütünüdür.","3":"Computer (bilgisayar); bilgiyi işleyen ve depolayan tekil elektronik cihazdır."},"vurgulu":false},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 09","metin":"Which entity is formally identified as \\"the largest known public network in the world, connecting millions of computers around the world\\"?","secenekler":["database","computer","Internet","component","peripheral"],"dogruCevap":2,"explanation":"Doğru cevap Internet terimidir. Soru kökündeki \'largest known public network in the world\' (dünyada bilinen en büyük kamuya açık ağ) ifadesi doğrudan İnternet\'i tanımlar.","wrongExplanations":{"0":"Database (veritabanı); verilerin depolandığı organize elektronik koleksiyondur, küresel bir iletişim ağı değildir.","1":"Computer (bilgisayar); tekil bir dijital bilgi işleme cihazıdır.","3":"Component (bileşen); bilgisayar kasasının içindeki donanım aygıtıdır.","4":"Peripheral (çevre birimi); bilgisayara harici olarak bağlanan ek yardımcı aygıttır."},"vurgulu":true},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 10","metin":"Which fundamental IT hardware is defined as \\"an electronic, digital device that stores and processes information\\"?","secenekler":["peripheral","software","database","computer","network"],"dogruCevap":3,"explanation":"Doğru cevap computer (bilgisayar) terimidir. \'An electronic, digital device that stores and processes information\' (bilgi depolayan ve işleyen elektronik, dijital cihaz) bilgisayar kavramının standart resmi tanımıdır.","wrongExplanations":{"0":"Peripheral (çevre birimi); bilgisayara harici olarak bağlanan yardımcı donanım aygıtıdır.","1":"Software (yazılım); fiziksel bir cihaz değil, program kodları ve talimatlar bütünüdür.","2":"Database (veritabanı); elektronik bilgi koleksiyonudur, bağımsız bir dijital cihaz değildir.","4":"Network (ağ); tekil bir cihaz değil, kaynak paylaşımı için birbirine bağlanmış bilgisayarlar bütünüdür."},"vurgulu":false},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 11","metin":"In computer hardware architecture, while external units like printers and scanners are peripherals, internal devices like the motherboard and hard disk drive (HDD) are classified as:","secenekler":["applications","accessories","databases","networks","components"],"dogruCevap":4,"explanation":"Doğru cevap components (bileşenler) terimidir. Kasa dışındaki harici donanımlar çevre birimi (peripheral) olarak adlandırılırken; anakart (motherboard) ve dahili sabit sürücü (HDD) gibi kasa içi donanımlar bileşen (component) olarak sınıflandırılır.","wrongExplanations":{"0":"Applications (uygulamalar); donanım değil, kullanıcıya yönelik çalışan yazılımlardır.","1":"Accessories (aksesuarlar); kasa içindeki bileşenleri değil, harici çevre birimlerini (peripherals) ifade eden eşanlamlı terimdir.","2":"Databases (veritabanları); fiziksel donanım aygıtı değil, organize veri saklama sistemleridir.","3":"Networks (ağlar); bilgisayarlar arasındaki bağlantı ve iletişim sistemleridir."},"vurgulu":true},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 12","metin":"In professional software engineering, the core data processed by a business application should typically be stored in a:","secenekler":["peripheral device","relational database","hardware processor","temporary register","public network"],"dogruCevap":1,"explanation":"Doğru cevap relational database (ilişkisel veritabanı) seçeneğidir. Standart yazılım geliştirme kurallarına göre uygulama verilerinin düzenli, tutarlı ve hızlı erişilebilir bir ilişkisel veritabanında saklanması esastır.","wrongExplanations":{"0":"Peripheral device (çevre birimi aygıtı); veri depolama yönetim yapısı değil, harici donanım eklentisidir.","2":"Hardware processor (donanım işlemcisi); veri saklama yapısı değil, komut işleme merkezidir.","3":"Temporary register (geçici yazmaç); işlemci içi çok küçük ve anlık bellek alanıdır, kalıcı uygulama verisi saklamaz.","4":"Public network (kamusal ağ); veri iletişim ortamıdır, verilerin organize biçimde depolandığı veritabanı değildir."},"vurgulu":false},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 13","metin":"Which global IT infrastructure is widely and metaphorically referred to in technical literature as an \\"information superhighway\\"?","secenekler":["Internet","database","software","computer","hardware"],"dogruCevap":0,"explanation":"Doğru cevap Internet terimidir. Küresel ölçekte milyonlarca ağı ve bilgisayarı birbirine bağlayan kamuya açık ağ altyapısı literatürde popüler olarak \'information superhighway\' (bilgi otobanı) olarak adlandırılır.","wrongExplanations":{"1":"Database (veritabanı); verilerin satır ve sütunlarda depolandığı koleksiyondur, bilgi otobanı metaforuyla anılmaz.","2":"Software (yazılım); bilgisayarda çalışan programların genel adıdır.","3":"Computer (bilgisayar); verileri işleyen tekil elektronik aygıttır.","4":"Hardware (donanım); bilgisayar sistemlerinin fiziksel bileşenlerinin bütünüdür."},"vurgulu":false},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 14","metin":"A resilient software application should be engineered to function properly with or without the presence of a solid:","secenekler":["relational database","peripheral scanner","hardware accessory","network connection","internal component"],"dogruCevap":3,"explanation":"Doğru cevap network connection (ağ bağlantısı) ifadesidir. Kaliteli yazılım mimarisi ilkelerine göre bir program, sağlam bir ağ bağlantısı olsa da olmasa da (çevrimdışı ve çevrimiçi koşullarda) kararlı şekilde çalışabilmelidir.","wrongExplanations":{"0":"Relational database (ilişkisel veritabanı); verilerin saklanacağı ana yapıdır, bağlantı varlığı gereksinimini ifade etmez.","1":"Peripheral scanner (çevre birimi tarayıcısı); özel bir harici donanımdır, genel bağlantı dayanıklılık kuralıyla doğrudan ilgili değildir.","2":"Hardware accessory (donanım aksesuarı); harici aygıtları ifade eder, bağlantı esnekliği ilkesini temsil etmez.","4":"Internal component (dahili bileşen); bilgisayarın anakart veya işlemci gibi temel parçasıdır ve eksikliği halinde sistem donanımsal olarak çalışamaz."},"vurgulu":false},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 15","metin":"To ensure broad user compatibility, a standard computer program should be capable of running smoothly without requiring any extra:","secenekler":["computer screens","operating systems","peripheral devices","internal processors","relational databases"],"dogruCevap":2,"explanation":"Doğru cevap peripheral devices (çevre birimi aygıtları) seçeneğidir. Yazılım geliştirme prensiplerine göre bir programın yaygın kullanılabilmesi için fazladan harici çevre birimlerine (extra peripherals) bağımlı kalmadan çalışabilmesi hedeflenir.","wrongExplanations":{"0":"Computer screens (bilgisayar ekranları); bir bilgisayarın temel görüntüleme arabirimidir, fazladan eklenti koşulunu nitelemez.","1":"Operating systems (işletim sistemleri); yazılımların çalışması için zorunlu olan temel sistem ortamıdır.","3":"Internal processors (dahili işlemciler); program kodlarını yürüten zorunlu donanım birimidir.","4":"Relational databases (ilişkisel veritabanları); verilerin saklandığı yapıdır, harici donanım eklentisi değildir."},"vurgulu":false},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 16","metin":"Everyday computer tools such as Microsoft Word, Adobe Photoshop, and Mozilla Firefox are formally categorized as:","secenekler":["hardware devices","internal components","network protocols","application programs","external peripherals"],"dogruCevap":3,"explanation":"Doğru cevap application programs (uygulama programları) terimidir. Kelime işlemci (Word), görsel düzenleyici (Photoshop) ve web tarayıcısı (Firefox) gibi son kullanıcının belirli görevleri gerçekleştirmesini sağlayan yazılımlar uygulama (application) sınıfına girer.","wrongExplanations":{"0":"Hardware devices (donanım aygıtları); fiziksel ve somut bilişim cihazlarıdır, yazılım programları değildir.","1":"Internal components (dahili bileşenler); kasa içindeki anakart ve sabit disk gibi donanım parçalarıdır.","2":"Network protocols (ağ protokolleri); ağ üzerindeki iletişim kurallarını belirleyen standartlardır.","4":"External peripherals (harici çevre birimleri); yazıcı ve tarayıcı gibi harici donanım aygıtlarıdır."},"vurgulu":true},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 17","metin":"Which structural IT concept fundamentally organizes data into \\"rows, columns, indexes, and keys\\" for rapid retrieval?","secenekler":["database","software","computer","hardware","Internet"],"dogruCevap":0,"explanation":"Doğru cevap database (veritabanı) terimidir. Verilerin hızlı ve düzenli erişim amacıyla satırlar (rows), sütunlar (columns), indeksler (indexes) ve anahtarlar (keys) halinde yapılandırılması doğrudan veritabanı mimarisinin belirleyici özelliğidir.","wrongExplanations":{"1":"Software (yazılım); bilgisayarda çalışan programların genel adıdır, bu tablo ve indeks yapısını doğrudan tanımlamaz.","2":"Computer (bilgisayar); verileri işleyen fiziksel dijital cihazdır.","3":"Hardware (donanım); fiziksel aygıtların genel sınıflandırmasıdır.","4":"Internet (İnternet); küresel bilgisayar ağıdır, verileri satır-sütun şeklinde saklayan yapı değildir."},"vurgulu":false},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 18","metin":"In IT taxonomy, both internal components (e.g., motherboard) and external peripherals (e.g., scanner) are unified under the term:","secenekler":["database","software","hardware","network","Internet"],"dogruCevap":2,"explanation":"Doğru cevap hardware (donanım) terimidir. Donanım kavramı; hem kasa içi dahili bileşenleri (components) hem de kasa dışı harici çevre birimlerini (peripherals) çatısı altında toplayan genel fiziksel üst kategoridir.","wrongExplanations":{"0":"Database (veritabanı); organize elektronik bilgi havuzudur, donanımları kapsamaz.","1":"Software (yazılım); donanım üzerinde çalışan fiziksel olmayan program kodlarıdır.","3":"Network (ağ); bilgisayarlar arasındaki iletişim ve paylaşım bağlantısıdır.","4":"Internet (İnternet); küresel kamuya açık bilgisayar ağıdır."},"vurgulu":true},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 19","metin":"Which specific hardware classification is technically synonymous with the term \\"accessory\\" attached externally to a computer?","secenekler":["component","peripheral","database","software","Internet"],"dogruCevap":1,"explanation":"Doğru cevap peripheral (çevre birimi) terimidir. Bilgisayara dışarıdan bağlanan harici eklentiler (external add-on) teknik terminolojide eşanlamlı olarak \'accessory\' (aksesuar) terimiyle ifade edilir.","wrongExplanations":{"0":"Component (bileşen); kasa içindeki dahili donanımlardır, aksesuar olarak adlandırılmaz.","2":"Database (veritabanı); dijital veri koleksiyonudur, donanım aksesuarı değildir.","3":"Software (yazılım); program ve talimatlar bütünüdür, fiziksel aksesuar değildir.","4":"Internet (İnternet); dünya çapındaki kamuya açık ağdır."},"vurgulu":true},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 20","metin":"In formal technical documentation and professional English, the colloquial abbreviation \\"app\\" must be formally written as:","secenekler":["attachment","appliance","apparatus","algorithm","application"],"dogruCevap":4,"explanation":"Doğru cevap application terimidir. Günlük dilde \'app\' olarak kısaltılan terimin resmi teknik raporlardaki ve akademik bilişim terminolojisindeki standart ve tam karşılığı \'application\'dır.","wrongExplanations":{"0":"Attachment (eklenti); genellikle e-postalara eklenen harici dosyaları ifade eder.","1":"Appliance (cihaz/aygıt); genellikle elektrikli ev aletlerini veya amaca yönelik özel donanım kutularını tanımlar.","2":"Apparatus (aygıt/aparat); laboratuvar veya teknik mekanik düzenekleri ifade eden bir kelimedir.","3":"Algorithm (algoritma); bir problemi çözmek için adım adım izlenen mantıksal kurallar kümesidir."},"vurgulu":true}]'))},8662,e=>{e.v(JSON.parse('[{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 01","metin":"Which technical term is formally defined as \\"an error in a computer program\\"?","secenekler":["crash","error","bug","abort","patch"],"dogruCevap":2,"explanation":"Doğru cevap bug terimidir. Soru kökündeki \'an error in a computer program\' ifadesi doğrudan bir yazılım programının kod yapısındaki kusur ve hataları tanımlayan teknik kalıptır.","wrongExplanations":{"0":"Crash; donanım arızası veya ciddi bir yazılım hatası nedeniyle sistemin aniden durması veya kilitlenmesidir (\'a computer failure\').","1":"Error; teknik terminolojide dikkatsizlik, bilgisizlik veya yanlış muhakeme kaynaklı hatalı eylemleri (\'incorrect action\') niteler.","3":"Abort; bir süreci veya programı tamamlanmadan önce zorla yarıda kesme ve durdurma işlemidir (\'to end before completion\').","4":"Patch; yazılımlardaki hataları gidermek veya sistemi güncellemek amacıyla yayınlanan ek onarım kod parçasıdır."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 02","metin":"The formal technical definition \\"to end a program or a process before its completion\\" refers to which of the following verbs?","secenekler":["abort","boot","compile","execute","debug"],"dogruCevap":0,"explanation":"Doğru cevap abort fiilidir. Tanımda geçen \'to end a program or a process before its completion\' kalıbı, bir işlemin olağan döngüsünü bitirmeden zorunlu olarak durdurulmasını ifade eder.","wrongExplanations":{"1":"Boot; bilgisayar donanımının işletim sistemini belleğe yükleyip ilk başlatma sürecini ifade eden eylemdir.","2":"Compile; geliştirici tarafından yazılan kaynak kodun makinenin yürütebileceği ikili (binary) formata dönüştürülmesidir.","3":"Execute; bir bilgisayar programını belleğe alıp fiilen başlatmak ve çalıştırmak için kullanılan en temel teknik fiildir.","4":"Debug; kaynak koddaki mantıksal veya sözdizimsel hataların tespit edilip temizlenmesi sürecidir."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 03","metin":"An \\"incorrect action attributable to poor judgment, ignorance, or inattention\\" is formally classified in technical language as an:","secenekler":["crash","bug","feature","error","abort"],"dogruCevap":3,"explanation":"Doğru cevap error terimidir. Soru kökündeki \'incorrect action attributable to poor judgment, ignorance, or inattention\' tanımı; insan faktörü, ihmal veya dikkatsizlik kaynaklı hatalı eylemleri kod hatalarından (bug) ayıran resmi ifadedir.","wrongExplanations":{"0":"Crash; donanımsal arıza ya da ağır bir kod hatası yüzünden sistemin tamamen kilitlenip kapanması durumudur.","1":"Bug; bir bilgisayar programının kaynak kodunda yer alan mantıksal kusur ve bozukluktur (\'an error in a computer program\').","2":"Feature; bir yazılım programının yapması planlanan ve beklenen meşru işlevsel özelliğidir (\'supposed to do\').","4":"Abort; yazılımın kilitlenmesi veya kullanıcı müdahalesiyle bir sürecin vaktinden önce durdurulması eylemidir."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 04","metin":"Which of the following terms describes \\"a computer failure due to faulty hardware or a serious software bug\\"?","secenekler":["error","crash","abort","bug","patch"],"dogruCevap":1,"explanation":"Doğru cevap crash terimidir. Tanımda yer alan \'a computer failure due to faulty hardware or a serious software bug\' ifadesi, sistemin beklenmedik şekilde durmasını ve yanıt veremez hale gelmesini niteleyen anahtar tanımdır.","wrongExplanations":{"0":"Error; dikkatsizlik veya yanlış muhakemeden kaynaklanan insan eylemi hatasıdır (\'incorrect action\').","2":"Abort; programın tamamlanmasını beklemeden işlemi dışarıdan manuel veya zorunlu olarak sonlandırmaktır.","3":"Bug; donanım arızası veya sistemik çöküş değil, yazılım kodu içindeki belirli bir hatadır.","4":"Patch; mevcut bir yazılım hatasını gidermek için üretici tarafından sonradan sağlanan düzeltme paketidir."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 05","metin":"What is considered the most precise technical verb used \\"to start a program on a computer\\"?","secenekler":["boot","abort","debug","compile","execute"],"dogruCevap":4,"explanation":"Doğru cevap execute fiilidir. Bir bilgisayar programını genel anlamda çalıştırmak (\'to start a program on a computer\') eylemi için teknik terminolojideki en doğru ve resmi fiil execute olarak kabul edilir.","wrongExplanations":{"0":"Boot; genel bir kullanıcı programını değil, özellikle bir işletim sistemini ilk açılışta başlatmayı tanımlayan fiildir.","1":"Abort; bir programı başlatmanın tam aksine, süreci tamamlanmadan önce zorla durdurmaktır.","2":"Debug; bir programı çalıştırmak değil, programın kodlarındaki kusurları ayıklama işlemidir.","3":"Compile; programı çalıştırmadan önce kaynak kodunu makine diline (binary) dönüştürme sürecidir."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 06","metin":"Which technical verb is specifically preferred when starting a computer program, \\"when the software in question is an operating system\\"?","secenekler":["boot","crash","abort","compile","execute"],"dogruCevap":0,"explanation":"Doğru cevap boot fiilidir. Teknik dilde bir uygulama genel olarak execute edilirken; söz konusu yazılım bir işletim sistemi olduğunda (\'when the software in question is an operating system\') başlatma eylemi için boot terimi kullanılır.","wrongExplanations":{"1":"Crash; işletim sisteminin başlamasını değil, donanım veya yazılım arızasıyla çöküp kilitlenmesini ifade eder.","2":"Abort; çalışan bir işlemin tamamlanamadan kesilip iptal edilmesini tanımlar.","3":"Compile; kaynak kodun derleyici vasıtasıyla ikili dosyalara dönüştürülme evresidir.","4":"Execute; genel yazılım başlatma eylemlerinde kullanılan üst terimdir; işletim sistemi önyüklemesi için özelleşmiş hali boot\'tur."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 07","metin":"In software terminology, \\"something a computer program is supposed to do, often serving as a reason to upgrade\\" is known as a:","secenekler":["bug","error","feature","patch","crash"],"dogruCevap":2,"explanation":"Doğru cevap feature terimidir. \'Something a computer program is supposed to do\' ifadesi, yazılımın yapması amaçlanan niteliği yani özelliği belirtir ve kullanıcıların üst sürüme geçme gerekçesini oluşturur.","wrongExplanations":{"0":"Bug; yazılımın yapması beklenen işlev değil, kodda meydana gelen istenmeyen kusur veya bozukluktur.","1":"Error; kullanıcının ya da geliştiricinin dikkatsizliğinden kaynaklanan hatalı eylemdir.","3":"Patch; mevcut özellikleri onarmak veya güncellemek için dağıtılan yama yazılımıdır.","4":"Crash; yazılımın beklenen işlevi yerine getiremeyip tamamen çökmesi ve sonlanmasıdır."},"vurgulu":false},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 08","metin":"A hardware component or software program that is \\"capable of being used without modification\\" is defined as:","secenekler":["proprietary","virtualized","compiled","uncompressed","compatible"],"dogruCevap":4,"explanation":"Doğru cevap compatible (uyumlu) terimidir. Tanımdaki \'capable of being used without modification\' kalıbı, bir bileşenin hiçbir değişikliğe gerek duymadan doğrudan sistemle uyum içinde çalışabilmesini ifade eder.","wrongExplanations":{"0":"Proprietary; özel mülkiyete ait, kaynak kodu gizli tutulan ve lisans kısıtlamaları olan teknolojidir.","1":"Virtualized; fiziksel bir donanımın yazılımsal katmanlar aracılığıyla taklit edilmesidir.","2":"Compiled; kaynak kodun derleyici yardımıyla ikili makine koduna dönüştürülmüş halidir.","3":"Uncompressed; arşivlenmiş veya sıkıştırılmış bir dosyanın orijinal boyutuna açılmış durumudur."},"vurgulu":false},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 09","metin":"Software in which the license stipulates that the user \\"cannot see, edit, or manipulate the source code\\" is categorized as:","secenekler":["Open source software","Closed source software","Compatible software","Emulation software","Standalone software"],"dogruCevap":1,"explanation":"Doğru cevap Closed source software (kapalı kaynak yazılım) modelidir. \'Cannot see, edit, or manipulate the source code\' ifadesi, lisans koşullarının kod erişimini ve düzenlenmesini kesinlikle yasakladığını belirtir.","wrongExplanations":{"0":"Open source software; kaynak kodları herkese açık olan ve serbestçe değiştirilmesine izin verilen yazılımlardır.","2":"Compatible software; ek bir uyarlama gerektirmeden belirli bir donanım veya platformla çalışan yazılımlardır.","3":"Emulation software; farklı bir mimari veya işletim sistemini taklit ederek yabancı yazılımları çalıştırmaya yarayan araçlardır.","4":"Standalone software; ağ bağlantısına veya başka harici kütüphanelere ihtiyaç duymadan tek başına çalışan yazılımlardır."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 10","metin":"Which term designates technology that is formally defined as \\"privately developed and owned technology\\"?","secenekler":["open source","peripheral","compatible","proprietary","executable"],"dogruCevap":3,"explanation":"Doğru cevap proprietary (tescilli/özel mülk) terimidir. Soru kökündeki \'privately developed and owned technology\' ifadesi, hakları tamamen özel bir kişi veya kuruluşa ait olan ve izin alınmadan değiştirilemeyen teknolojiyi tanımlar.","wrongExplanations":{"0":"Open source; mülkiyeti topluluğa veya genel kullanıma açık bırakılan, kodları paylaşılan yazılım modelidir.","1":"Peripheral; bilgisayara dışarıdan bağlanan yazıcı veya tarayıcı gibi harici çevre birimleridir.","2":"Compatible; sistem bileşenleriyle modifikasyonsuz çalışabilen parçaları niteleyen sıfattır.","4":"Executable; bilgisayar donanımı tarafından doğrudan icra edilebilen çalıştırılabilir dosya formatıdır."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 11","metin":"A software application whose code is distributed \\"allowing programmers to alter and change the original software as much as they like\\" is called:","secenekler":["Closed source software","Proprietary software","Commercial software","Firmware software","Open source software"],"dogruCevap":4,"explanation":"Doğru cevap Open source software (açık kaynak yazılım) terimidir. Kodun geliştiricilere dağıtılarak diledikleri gibi değiştirilmesine (\'allowing programmers to alter and change\') olanak tanınması açık kaynak modelinin temel ilkesidir.","wrongExplanations":{"0":"Closed source software; kodların kullanıcılardan gizlendiği ve üzerinde değişiklik yapılmasına izin verilmeyen modeldir.","1":"Proprietary software; özel bir şirkete ait olan ve lisans kısıtlamalarıyla korunan tescilli yazılımdır.","2":"Commercial software; genellikle ticari gelir elde etmek amacıyla satılan ve kaynak kodları kapalı tutulan yazılımlardır.","3":"Firmware software; donanım çiplerinin içine kalıcı olarak yazılmış düşük seviyeli denetleyici yazılımlardır."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 12","metin":"Which technical role is formally defined as \\"a person who uses a product or service on a computer\\"?","secenekler":["software developer","end user","system programmer","site administrator","database architect"],"dogruCevap":1,"explanation":"Doğru cevap end user (son kullanıcı) kavramıdır. \'A person who uses a product or service on a computer\' ifadesi; yazılımı tasarlayan veya kodlayan değil, sistemi doğrudan tüketen nihai kullanıcıyı tanımlar.","wrongExplanations":{"0":"Software developer; yazılımın gereksinimlerini belirleyen ve programlama kodunu yazan teknik uzmandır.","2":"System programmer; işletim sistemi ve donanım düzeyinde düşük seviyeli kodlar geliştiren uzmandır.","3":"Site administrator; bir web sitesinin veya sunucu altyapısının teknik işleyişinden sorumlu yöneticidir.","4":"Database architect; veri tabanı yapısını, tablolarını ve ilişkisel modellerini kurgulayan teknik personPointtir."},"vurgulu":false},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 13","metin":"Which IT professional is defined as \\"a person who writes or modifies computer programs or applications\\"?","secenekler":["programmer","end user","moderator","operator","publisher"],"dogruCevap":0,"explanation":"Doğru cevap programmer (programcı / yazılım geliştirici) terimidir. Soru kökündeki \'a person who writes or modifies computer programs or applications\' ifadesi doğrudan programcı rolünü açıklar.","wrongExplanations":{"1":"End user; geliştirilen yazılımı kendi iş süreçleri için kullanan nihai tüketici veya çalışandır.","2":"Moderator; çevrim içi platformlarda kullanıcı içeriklerini denetleyen ve kuralları uygulayan kişidir.","3":"Operator; bilgisayar sistemlerinin veya donanım aygıtlarının günlük fiziksel operasyonunu izleyen görevlidir.","4":"Publisher; üretilen dijital içerikleri veya yazılım ürünlerini pazara sunup yayımlayan kuruluştur."},"vurgulu":false},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 14","metin":"Which utility is used in software engineering to \\"turn the source code into a binary file\\"?","secenekler":["text editor","debugger","compiler","emulator","archiver"],"dogruCevap":2,"explanation":"Doğru cevap compiler (derleyici) terimidir. Kaynak kodun işlemci tarafından çalıştırılabilir ikili dosyalara (\'turn the source code into a binary file\') dönüştürülmesini sağlayan araç derleyicidir.","wrongExplanations":{"0":"Text editor; programcıların kaynak kod metinlerini yazdığı ve düzenlediği temel araçtır; ikili dosya üretmez.","1":"Debugger; koddaki mantıksal hataları bulup adım adım incelemek amacıyla kullanılan analiz aracıdır.","3":"Emulator; bir donanım mimarisini başka bir mimari üzerinde taklit eden sanallaştırma katmanıdır.","4":"Archiver; dosyaları sıkıştırarak paketleyen veya arşivden çıkaran yazılımdır (unzip)."},"vurgulu":false},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 15","metin":"A software development tool designed specifically to \\"find and fix bugs in the source code\\" is called a:","secenekler":["compiler","emulator","web browser","debugger","terminal"],"dogruCevap":3,"explanation":"Doğru cevap debugger (hata ayıklayıcı) terimidir. \'Find and fix bugs in the source code\' ifadesi, kod içi hataları tespit etmek ve gidermek için çalışan aracı doğrudan niteler.","wrongExplanations":{"0":"Compiler; hatayı ayıklamaz; hatasız kabul edilen kaynak kodu makine koduna (binary) dönüştürür.","1":"Emulator; hedef donanımın çalışma ortamını taklit ederek yabancı yazılımları çalıştırmaya yarar.","2":"Web browser; HTML ve web tabanlı dilleri işleyerek kullanıcılara sunan internet istemcisidir.","4":"Terminal; komut satırı arayüzü üzerinden işletim sistemi komutlarını çalıştırmaya yarayan ekrandır."},"vurgulu":false},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 16","metin":"Running software written specifically for Windows on a Macintosh or Linux computer typically requires an emulation layer or a:","secenekler":["Central Processing Unit (CPU)","Virtual Machine (VM)","Command Line Interface (CLI)","Relational Database System (RDBMS)","Graphical User Interface (GUI)"],"dogruCevap":1,"explanation":"Doğru cevap Virtual Machine (VM) - Sanal Makine terimidir. Farklı bir platform için derlenmiş yazılımların yerel donanımda çalışabilmesi için emülasyon yazılımı veya bir sanal makine katmanı kurulması zorunludur.","wrongExplanations":{"0":"Central Processing Unit (CPU); bilgisayarın temel işlem birimidir, platformlar arası yazılım çevirisi sağlayan bir araç değildir.","2":"Command Line Interface (CLI); komutların metin tabanlı girildiği kullanıcı arayüzüdür.","3":"Relational Database System (RDBMS); verileri tablolar halinde organize eden ilişkisel veritabanı yönetim sistemidir.","4":"Graphical User Interface (GUI); kullanıcıların pencereler ve simgeler yoluyla etkileşim kurduğu grafiksel arayüzdür."},"vurgulu":false},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 17","metin":"In the standard 4-step bug fixing workflow of an open source project, which action is performed first?","secenekler":["Download and unzip the source code","Use an IDE and debugger on the code","Compile the code into a binary file","Send the bug fix back to the team","File a bug report and await a patch"],"dogruCevap":0,"explanation":"Doğru cevap \'Download and unzip the source code\' seçeneğidir. Açık kaynaklı bir yazılımda hata düzeltme sürecinin ilk adımı (Step 1), kaynak kodun resmi depodan indirilmesi ve sıkıştırılmış halden çıkarılmasıdır.","wrongExplanations":{"1":"Use an IDE and debugger on the code; sürecin ikinci adımıdır (Step 2) ve indirilen kod üzerindeki hatayı bulup onarmayı içerir.","2":"Compile the code into a binary file; üçüncü adımdır (Step 3) ve onarılan kodun çalışabilir ikili formata dönüştürülmesini sağlar.","3":"Send the bug fix back to the team; sürecin dördüncü ve son adımıdır (Step 4) ve yamanın geliştirici ekibe geri iletilmesini kapsar.","4":"File a bug report and await a patch; açık kaynak iş akışının değil, kod erişimi olmayan kapalı kaynaklı (proprietary) modellerin kısıtlı çözüm yoludur."},"vurgulu":false},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 18","metin":"When an IT professional discovers a software bug within a proprietary, closed-source codebase such as Microsoft Word, the only viable course of action is to:","secenekler":["modify and recompile the binary file directly","download the source code and run a local debugger","rewrite the software logic in an open repository","distribute a custom patch across user networks","file an official bug report and await a fix"],"dogruCevap":4,"explanation":"Doğru cevap \'file an official bug report and await a fix\' seçeneğidir. Kapalı kaynaklı ve tescilli yazılımlarda kaynak koda erişim ve müdahale izni bulunmadığı için kullanıcıların tek seçeneği bir hata raporu (bug report) oluşturup üretici firmanın bunu düzeltmesini beklemektir.","wrongExplanations":{"0":"modify and recompile the binary file directly; kapalı kaynak lisans koşullarını ihlal eder ve teknik olarak uygulanabilir bir standart prosedür değildir.","1":"download the source code and run a local debugger; kapalı kaynaklı projelerde kaynak kod kamuya sunulmadığı için bu adım imkânsızdır.","2":"rewrite the software logic in an open repository; telif haklarıyla korunan tescilli kod tabanlarında yasal olarak gerçekleştirilemez.","3":"distribute a custom patch across user networks; kaynak koda erişim olmadan resmi bir yama üretip dağıtmak mümkün değildir."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 19","metin":"A software suite that integrates a source code editor, build automation tools, and a debugger into a single graphical workspace is known as an:","secenekler":["Operating System Interface (OSI)","Open Database Connectivity (ODBC)","Integrated Development Environment (IDE)","Enterprise Resource Planning (ERP)","Content Management System (CMS)"],"dogruCevap":2,"explanation":"Doğru cevap Integrated Development Environment (IDE) - Tümleşik Geliştirme Ortamı terimidir. Geliştiricilerin kod yazma, hata ayıklama ve derleme işlemlerini tek bir çatı altında yürüttüğü ortam IDE olarak adlandırılır.","wrongExplanations":{"0":"Operating System Interface (OSI); ağ mimarilerini veya işletim sistemi çağrılarını ifade eden katmandır.","1":"Open Database Connectivity (ODBC); uygulamaların veritabanı yönetim sistemlerine erişimini standartlaştıran bir arayüzdür.","3":"Enterprise Resource Planning (ERP); bir kurumun muhasebe, tedarik ve insan kaynakları gibi tüm iş süreçlerini yöneten kurumsal yazılımdır.","4":"Content Management System (CMS); web sitelerindeki dijital içeriklerin kodlama bilmeden oluşturulup yönetilmesini sağlayan yazılımdır."},"vurgulu":false},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 20","metin":"In Information Technology education, learning at least one programming language is considered essential because writing code directly:","secenekler":["eliminates the need for software licenses","guarantees full hardware compatibility across systems","allows full control over proprietary systems","forces the developer to think like a computer","removes the necessity of compiling binary code"],"dogruCevap":3,"explanation":"Doğru cevap \'forces the developer to think like a computer\' seçeneğidir. Bilişim uzmanlarının programlama öğrenmesi gerektiğinin en temel sebebi, algoritmik düşünce yapısını geliştirmesi ve bireyi bir bilgisayar gibi katı mantıkla düşünmeye zorlamasıdır (\'think like a computer\').","wrongExplanations":{"0":"eliminates the need for software licenses; kod yazmayı bilmek üçüncü taraf yazılım lisanslama zorunluluğunu ortadan kaldırmaz.","1":"guarantees full hardware compatibility across systems; programlama bilmek yazılan yazılımın her donanımla evrensel olarak uyumlu çalışacağını garanti etmez.","2":"allows full control over proprietary systems; tescilli sistemlerin lisansı ve kapalı kaynak yapısı, programlama bilinse dahi kod kontrolünü engeller.","4":"removes the necessity of compiling binary code; program yazmak derleme ihtiyacını kaldırmaz, bilakis kaynak kodun ikili makine koduna derlenmesini zorunlu kılar."},"vurgulu":false}]'))},65807,e=>{e.v(JSON.parse('[{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 01","metin":"Which of the following technical terms is formally defined as the \\"concurrent execution of two or more tasks by a processor\\"?","secenekler":["Dual-booting","Data compression","Multitasking","Virtualization","Convergence"],"dogruCevap":2,"explanation":"Doğru cevap Multitasking (çoklu görev) terimidir. Soru kökündeki \'concurrent execution of two or more tasks by a processor\' (bir işlemci tarafından iki veya daha fazla görevin eşzamanlı yürütülmesi) ifadesi doğrudan çoklu görev mimarisini niteleyen temel tanımdır.","wrongExplanations":{"0":"Dual-booting (çift önyükleme); bir bilgisayarda iki farklı işletim sisteminin kurulu olması ve açılışta bunlardan birinin seçilerek donanım üzerinde çalıştırılması yöntemidir.","1":"Data compression (veri sıkıştırma); depolama alanından veya veri aktarım süresinden tasarruf etmek amacıyla verilerin paketlenmesi işlemidir.","3":"Virtualization (sanallaştırma); fiziksel donanım kaynaklarının yazılımsal katmanlar aracılığıyla taklit edilip bağımsız ortamlar yaratılması sürecidir.","4":"Convergence (yakınsama); harici araçların ve uygulamaların temel işletim sistemi kurulumuna dahil edilerek tek çatı altında birleştirilmesidir."},"vurgulu":false},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 02","metin":"Which component represents the \\"lowest level or core of the operating system\\" responsible for controlling file systems and hardware drivers, positioned immediately above firmware?","secenekler":["Device driver module","System desktop manager","Command line interface","Basic input/output system","Operating system kernel"],"dogruCevap":4,"explanation":"Doğru cevap Operating system kernel (işletim sistemi çekirdeği) bileşenidir. Soru kökündeki \'lowest level or core of the operating system\' (işletim sisteminin en alt düzeyi veya çekirdeği) ifadesi doğrudan Kernel kavramını tanımlar.","wrongExplanations":{"0":"Device driver module (aygıt sürücüsü modülü); donanım birimlerinden gelen veriyi işletim sisteminin işleyebileceği formata dönüştüren yazılımdır, sistemin çekirdeği değildir.","1":"System desktop manager (sistem masaüstü yöneticisi); kullanıcıya pencereler ve grafiksel ögeler sunan üst düzey kullanıcı arayüzü katmanıdır.","2":"Command line interface (komut satırı arayüzü); sistemle metin tabanlı komutlar aracılığıyla etkileşim kurmayı sağlayan arayüzdür.","3":"Basic input/output system (BIOS); donanımı başlatan en alt düzey yazılımdır ancak işletim sisteminin bir parçası kabul edilmez."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 03","metin":"Which of the following refers to the lowest-level software on a PC that controls initial hardware startup but \\"isn\'t really a part of the operating system\\"?","secenekler":["Operating System Kernel","Basic Input/Output System (BIOS)","Device Driver Interface","Graphical Desktop Manager","Command Line Interpreter"],"dogruCevap":1,"explanation":"Doğru cevap Basic Input/Output System (BIOS)\'tur. Çekirdekten (Kernel) daha alt seviyede yer almasına rağmen \'isn\'t really a part of the operating system\' (işletim sisteminin gerçekte bir parçası değildir) ifadesi BIOS\'u Kernel\'dan ayıran en kritik sınav tetikleyicisidir.","wrongExplanations":{"0":"Operating System Kernel; donanım yönetimi ve dosya sistemlerinden sorumlu temel yapıdır ve doğrudan işletim sisteminin çekirdeğidir.","2":"Device Driver Interface; çevre birimleri ile işletim sistemi arasındaki veri iletişimini sağlayan yazılımsal sürücü katmanıdır.","3":"Graphical Desktop Manager; kullanıcı ile etkileşimi görsel simgeler üzerinden sağlayan üst seviye işletim sistemi katmanıdır.","4":"Command Line Interpreter; kullanıcının girdiği metin tabanlı komutları yorumlayan kabuk yazılımıdır."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 04","metin":"A technical interface that establishes a \\"text-only link between a computer and its operator\\" for system administration is officially known as a:","secenekler":["Graphical User Interface (GUI)","Virtual Machine Environment (VME)","Desktop Window Manager (DWM)","Command Line Interface (CLI)","Hardware Abstraction Layer (HAL)"],"dogruCevap":3,"explanation":"Doğru cevap Command Line Interface (CLI)\'dır. Soru kökündeki \'text-only link between a computer and its operator\' (bilgisayar ile operatörü arasındaki salt metin tabanlı bağlantı) ifadesi doğrudan CLI tanımıdır.","wrongExplanations":{"0":"Graphical User Interface (GUI); kullanıcı ile bilgisayar arasında metin tabanlı değil, simge ve görsel ögelere dayalı bağlantı (icon-based link) kurar.","1":"Virtual Machine Environment (VME); donanımı yazılımsal olarak taklit ederek yalıtılmış çalışma ortamı sağlayan yapıdır.","2":"Desktop Window Manager (DWM); pencerelerin ekrandaki grafiksel yerleşimini ve çizimini yöneten görsel katmandır.","4":"Hardware Abstraction Layer (HAL); donanım farklılıklarını işletim sistemi çekirdeğinden gizleyen alt düzey yazılım katmanıdır."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 05","metin":"Which type of user interface provides an \\"icon-based link between a computer and its operator\\", allowing interaction through visual elements?","secenekler":["Graphical User Interface (GUI)","Command Line Interface (CLI)","Basic Input/Output System (BIOS)","Virtual Machine Monitor (VMM)","Central Processing Unit (CPU)"],"dogruCevap":0,"explanation":"Doğru cevap Graphical User Interface (GUI)\'dır. \'Icon-based link between a computer and its operator\' (bilgisayar ile operatörü arasındaki simge tabanlı bağlantı) ifadesi doğrudan grafik kullanıcı arayüzünü tanımlar.","wrongExplanations":{"1":"Command Line Interface (CLI); simgelere değil, salt metin komutlarına (text-only link) dayanan kullanıcı arayüzüdür.","2":"Basic Input/Output System (BIOS); donanım açılışını yöneten ürün yazılımıdır, görsel kullanıcı arayüzü değildir.","3":"Virtual Machine Monitor (VMM); sanal makinelerin yönetimini ve donanım paylaşımını sağlayan hipervizör yazılımıdır.","4":"Central Processing Unit (CPU); bilgisayarın komutları işleyen fiziksel işlemci donanımıdır."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 06","metin":"Which type of software is responsible for \\"converting data from a component or peripheral into data that an operating system can use\\"?","secenekler":["Virtual machine","Operating kernel","File system shell","Device driver","Desktop manager"],"dogruCevap":3,"explanation":"Doğru cevap Device driver (aygıt sürücüsü) terimidir. Soru kökündeki \'converts the data from a component or peripheral into data that an operating system can use\' ifadesi aygıt sürücüsünün temel teknik tanımıdır.","wrongExplanations":{"0":"Virtual machine (sanal makine); fiziksel donanımı taklit ederek bağımsız sistem çalıştırmaya yarayan yazılımdır.","1":"Operating kernel (işletim sistemi çekirdeği); sistem kaynaklarını yöneten ana merkezdir, spesifik donanım verisi çevrimini sürücülere devreder.","2":"File system shell (dosya sistemi kabuğu); kullanıcının dosya ve dizin komutlarını girmesine olanak tanıyan arayüzdür.","4":"Desktop manager (masaüstü yöneticisi); pencereleri ve masaüstü simgelerini denetleyen grafiksel yazılımdır."},"vurgulu":false},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 07","metin":"Which of the following is defined as a software program that \\"mimics the performance of one or more hardware devices in order to run software independently of the actual hardware\\"?","secenekler":["Virtual Machine (VM)","Device Driver (DD)","Operating System (OS)","Terminal Shell (TS)","Desktop Manager (DM)"],"dogruCevap":0,"explanation":"Doğru cevap Virtual Machine (VM - Sanal Makine)\'dir. Soru kökündeki \'mimics the performance of one or more hardware devices in order to run software independently of the actual hardware\' ifadesi sanal makinelerin birebir akademik tanımıdır.","wrongExplanations":{"1":"Device Driver (DD); donanım birimlerinden gelen verileri işletim sisteminin anlayacağı forma dönüştüren yazılımdır.","2":"Operating System (OS); genel donanım yönetimini ve temel görevleri sağlayan çok görevli yazılım katmanıdır.","3":"Terminal Shell (TS); komut satırında yazılan komutları yorumlayan metin arayüzüdür.","4":"Desktop Manager (DM); kullanıcıya görsel çalışma alanı ve pencere kontrolleri sunan yazılımdır."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 08","metin":"What technical term describes \\"a set of strict rules for controlling read, write, and execute access to a file or directory\\"?","secenekler":["File compression","Data formatting","File permissions","Hidden attributes","Task scheduling"],"dogruCevap":2,"explanation":"Doğru cevap File permissions (dosya izinleri) kavramıdır. \'Strict rules for controlling read, write, and execute access\' (okuma, yazma ve çalıştırma erişimini denetleyen katı kurallar bütünü) ifadesi dosya izinlerinin ayırt edici tanımıdır.","wrongExplanations":{"0":"File compression (dosya sıkıştırma); dosya boyutunu küçülterek disk alanı veya aktarım süresi kazanma yöntemidir.","1":"Data formatting (veri biçimlendirme); depolama aygıtındaki eski verileri silip yeni veri depolamaya hazırlama eylemidir.","3":"Hidden attributes (gizli nitelikler); bir dosyanın dizin listelerinde varsayılan olarak görünmesini engelleyen ayarlardır.","4":"Task scheduling (görev zamanlama); belirli görevlerin veya komutların belirlenen zaman aralıklarında otomatik yürütülmesidir."},"vurgulu":false},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 09","metin":"Which method is formally defined as \\"a method of packing data in order to save disk storage space or download time\\"?","secenekler":["Partitioning","Formatting","Scheduling","Encrypting","Compression"],"dogruCevap":4,"explanation":"Doğru cevap Compression (sıkıştırma) yöntemidir. \'Packing data in order to save disk storage space or download time\' (disk alanından veya indirme süresinden tasarruf etmek amacıyla verileri paketleme yöntemi) ifadesi doğrudan sıkıştırmayı tanımlar.","wrongExplanations":{"0":"Partitioning (bölümleme); bir depolama sürücüsünü mantıksal bağımsız bölümlere ayırma işlemidir.","1":"Formatting (biçimlendirme); sürücüyü veri depolamaya hazırlarken içindeki verileri temizleme işlemidir.","2":"Scheduling (zamanlama); işlemci süreçlerinin sıraya konulması veya planlanması mekanizmasıdır.","3":"Encrypting (şifreleme); verilerin yetkisiz erişime karşı matematiksel algoritmalarla güvenli hale getirilmesidir."},"vurgulu":false},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 10","metin":"Which system procedure is defined as an action to \\"prepare a device to store data, erasing any existing data\\"?","secenekler":["Compress","Format","Launch","Upgrade","Archive"],"dogruCevap":1,"explanation":"Doğru cevap Format (biçimlendirmek) terimidir. Soru kökündeki \'prepare a device to store data, erasing any existing data\' (mevcut tüm verileri silerek bir aygıtı veri saklamaya hazır hale getirmek) ifadesi format işleminin teknik karşılığıdır.","wrongExplanations":{"0":"Compress (sıkıştırmak); verileri paketleyerek kapladığı depolama alanını azaltma eylemidir.","2":"Launch (başlatmak/çalıştırmak); bir yazılım uygulamasını belleğe yükleyip yürütmeye başlama işlemidir.","3":"Upgrade (yükseltmek); yazılım veya donanımı daha yeni ve gelişmiş bir sürüme güncelleme sürecidir.","4":"Archive (arşivlemek); verileri uzun süreli saklama amacıyla bir araya getirip yedekleme işlemidir."},"vurgulu":false},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 11","metin":"An item that \\"does not appear by default in a directory listing; normally for security reasons or to spare confusion in end users\\" is designated as a:","secenekler":["compressed file","formatted device","corrupted record","hidden file","read-only block"],"dogruCevap":3,"explanation":"Doğru cevap hidden file (gizli dosya) kavramıdır. \'Does not appear by default in a directory listing\' ve \'spare confusion in end users\' tetikleyicileri doğrudan gizli dosya tanımını oluşturur.","wrongExplanations":{"0":"Compressed file (sıkıştırılmış dosya); disk tasarrufu için paketlenmiş dosyadır, dizin listesinde varsayılan olarak görünür.","1":"Formatted device (biçimlendirilmiş aygıt); veri depolamaya hazırlanmış fiziksel depolama birimidir.","2":"Corrupted record (bozuk kayıt); veri bütünlüğü zarar görmüş ve okunamayan veri bloklarıdır.","4":"Read-only block (salt okunur blok); içeriği görüntülenebilen fakat üzerinde değişiklik veya silme yapılamayan veridir."},"vurgulu":false},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 12","metin":"The modern computing trend of integrating external utilities—such as notepads, media players, and web browsers—directly into the basic operating system install is termed:","secenekler":["Multitasking","Convergence","Virtualization","Fragmentation","Dual-booting"],"dogruCevap":1,"explanation":"Doğru cevap Convergence (yakınsama/kümelenme) terimidir. Not defteri, tarayıcı, medya oynatıcı gibi harici programların temel işletim sistemi kurulumuna dahil edilip tek bir potada toplanması kavramı \'convergence\' olarak adlandırılır.","wrongExplanations":{"0":"Multitasking (çoklu görev); bir işlemcinin birden fazla görevi eşzamanlı olarak yürütme yeteneğidir.","2":"Virtualization (sanallaştırma); donanım kaynaklarının yazılımsal olarak soyutlanıp sanal ortamlara bölünmesidir.","3":"Fragmentation (parçalanma); dosya bloklarının depolama aygıtı üzerinde farklı ve dağınık konumlara yazılması durumudur.","4":"Dual-booting (çift önyükleme); iki farklı işletim sisteminin tek bir bilgisayara kurulup açılışta seçilerek çalıştırılmasıdır."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 13","metin":"Which software component serves as a \\"toolkit for UNIX systems underlying numerous GUI window managers including KDE and Gnome\\"?","secenekler":["Microsoft MS-DOS","Apple Terminal","Linux Bash Shell","Free BSD Kernel","X Window System"],"dogruCevap":4,"explanation":"Doğru cevap X Window System (X / X11)\'dir. Soru kökündeki \'software toolkit for UNIX systems underlying numerous GUI window managers including KDE and Gnome\' ifadesi doğrudan X Pencere Sistemi\'ni tanımlar.","wrongExplanations":{"0":"Microsoft MS-DOS; Windows platformlarında geçmişte kullanılan temel metin tabanlı komut satırı arayüzüdür.","1":"Apple Terminal; Mac OS X işletim sisteminde yer alan komut satırı arayüzüdür (CLI).","2":"Linux Bash Shell; Unix ve Linux sistemlerde en yaygın kullanılan metin tabanlı komut kabuğudur.","3":"Free BSD Kernel; açık kaynaklı bir Unix işletim sistemi ailesinin çekirdek katmanıdır."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 14","metin":"Which of the following technical actions is defined as entering \\"information related to an account name and its password in order to access a computer resource\\"?","secenekler":["Log on / Sign in","Log off / Sign out","Format / Partition","Upgrade / Compress","Launch / Terminate"],"dogruCevap":0,"explanation":"Doğru cevap Log on / Sign in (oturum açmak) eylemidir. \'Enter information related to an account name and its password in order to access a computer resource\' ifadesi bir kaynağa hesap adı ve parola girerek erişmeyi tanımlar.","wrongExplanations":{"1":"Log off / Sign out (oturumu kapatmak); açık olan oturumu veya bilgisayar ağıyla olan bağlantıyı sonlandırma işlemidir.","2":"Format / Partition (biçimlendirme/bölümleme); depolama aygıtını bölme ve verileri silerek kullanıma hazırlama işlemleridir.","3":"Upgrade / Compress (yükseltme/sıkıştırma); yazılım sürümünü güncelleme veya dosya boyutunu paketleme işlemleridir.","4":"Launch / Terminate (başlatma/sonlandırma); bir uygulama programını çalıştırma veya çalışmasını durdurma eylemleridir."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 15","metin":"An operation executed to \\"terminate a connection to a computer or network resource\\" and end the current user session is defined as:","secenekler":["Log on / Sign in","Format / Erase","Log off / Sign out","Launch / Execute","Upgrade / Install"],"dogruCevap":2,"explanation":"Doğru cevap Log off / Sign out (oturumu kapatmak) eylemidir. \'Terminate a connection to a computer or network\' veya \'end a session\' ifadeleri oturumu güvenli şekilde sonlandırmayı ifade eder.","wrongExplanations":{"0":"Log on / Sign in; sisteme kullanıcı adı ve şifre girerek oturum açma işlemidir.","1":"Format / Erase; depolama birimindeki verileri silerek sürücüyü yeniden yapılandırma işlemidir.","3":"Launch / Execute; bir programı veya komutu işletim sistemi üzerinde çalıştırmaya başlama işlemidir.","4":"Upgrade / Install; sisteme yeni yazılım yükleme veya mevcut yazılımı üst sürüme geçirme eylemleridir."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 16","metin":"Running two separate operating systems natively on a single computer by selecting between them during the initial boot sequence is known as:","secenekler":["Multitasking","Dual-booting","Convergence","Compression","Formatting"],"dogruCevap":1,"explanation":"Doğru cevap Dual-booting (çift önyükleme) kavramıdır. Sanal makine katmanı kullanmadan, fiziksel donanım üzerinde açılış anında iki işletim sisteminden birinin seçilerek çalıştırılması dual-booting tekniğidir.","wrongExplanations":{"0":"Multitasking; işlemcinin aynı anda birden çok program sürecini yürütmesidir.","2":"Convergence; temel işletim sistemi paketinde tarayıcı ve araçların bir araya toplanmasıdır.","3":"Compression; dosya boyutunun depolama alanından tasarruf için küçültülmesidir.","4":"Formatting; disklerin veri saklamaya hazır hale getirilmesi için biçimlendirilmesidir."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 17","metin":"Which operating system is formally recognized as \\"an open source version of Unix developed by a volunteer team of programmers around the world\\"?","secenekler":["Microsoft Windows","Apple Mac OS X","Sun Solaris OS","FreeBSD System","GNU Linux OS"],"dogruCevap":4,"explanation":"Doğru cevap GNU Linux OS\'tur. \'An open source version of Unix developed by a volunteer team of programmers around the world\' ve Linus Torvalds öncülüğünde geliştirilme ifadeleri Linux\'un tanımlayıcı özellikleridir.","wrongExplanations":{"0":"Microsoft Windows; pazar payı yüksek olan ticari ve kapalı kaynak kodlu bir işletim sistemidir.","1":"Apple Mac OS X; Apple donanımları için optimize edilmiş ticari bir işletim sistemidir.","2":"Sun Solaris OS; kurumsal sunucularda kullanılan tescilli bir Unix türevidir.","3":"FreeBSD System; Berkeley Software Distribution kökenli gelişmiş bir işletim sistemidir."},"vurgulu":false},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 18","metin":"What is the generic term for the \\"multitasking software layer that lets you perform a wide array of lower level tasks\\" while providing a framework for productivity software?","secenekler":["Operating System (OS)","Virtual Machine (VM)","Word Processor (WP)","Device Driver (DD)","Web Browser (WB)"],"dogruCevap":0,"explanation":"Doğru cevap Operating System (OS - İşletim Sistemi)\'dir. \'Multitasking software layer that lets you perform a wide array of lower level tasks\' ve üretkenlik yazılımlarına altyapı (framework) sunma tanımı doğrudan işletim sistemini ifade eder.","wrongExplanations":{"1":"Virtual Machine (VM); donanımı taklit ederek bağımsız yazılım çalıştırmaya yarayan sanal ortamdır.","2":"Word Processor (WP); işletim sistemi üzerinde çalışan bir kelime işlemci uygulama yazılımıdır.","3":"Device Driver (DD); yalnızca belirli bir donanımın işletim sistemiyle haberleşmesini sağlayan yazılımdır.","4":"Web Browser (WB); web sayfalarını görüntülemeye yarayan bir uygulama yazılımıdır."},"vurgulu":false},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 19","metin":"While Windows utilizes MS-DOS and Mac OS X incorporates Terminal, what is the most popular Command Line Interface (CLI) used across Unix and Linux systems?","secenekler":["Aqua","GNOME","Bash","KDE","Aero"],"dogruCevap":2,"explanation":"Doğru cevap Bash kabuğudur. Unix ve Linux sistemlerinde kullanılan çok sayıda metin tabanlı komut satırı arayüzü (CLI) bulunmakla birlikte, en popüler olanı resmi olarak \'Bash\' olarak adlandırılır.","wrongExplanations":{"0":"Aqua; Mac OS X işletim sisteminin grafiksel kullanıcı arayüzü (GUI) görsel temasıdır.","1":"GNOME; Unix ve Linux sistemlerinde X-Windows üzerinde çalışan popüler bir grafik kullanıcı arayüzüdür (GUI).","3":"KDE; Unix sistemlerde yaygın olarak tercih edilen bir diğer grafiksel masaüstü ortamıdır (GUI).","4":"Aero; Microsoft Windows Vista ve Windows 7 sürümlerinde kullanılan grafik kullanıcı arayüzü görsel tasarımıdır."},"vurgulu":false},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 20","metin":"In Unix environments, which popular graphical desktop environment operates on top of the X Window System alongside KDE?","secenekler":["Terminal","MS-DOS","Ubuntu","GNOME","Solaris"],"dogruCevap":3,"explanation":"Doğru cevap GNOME masaüstü ortamıdır. Unix sistemlerinde X-Windows altyapısı üzerinde çalışan iki popüler grafiksel kullanıcı arayüzü (GUI) KDE ve GNOME\'dur.","wrongExplanations":{"0":"Terminal; Mac OS X veya Unix sistemlerde komut çalıştırmak için kullanılan metin tabanlı CLI aracıdır.","1":"MS-DOS; Microsoft Windows sistemlerinin temelinde yer alan geleneksel komut satırı arayüzüdür.","2":"Ubuntu; GNOME arayüzünü de kullanabilen, Debian tabanlı popüler ve ücretsiz bir Linux işletim sistemi dağıtımıdır.","4":"Solaris; Sun Microsystems tarafından geliştirilmiş ticari bir Unix işletim sistemidir."},"vurgulu":false}]'))},56235,e=>{e.v(JSON.parse('[{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 01","metin":"Which of the following stages in the software development cycle is defined as \\"normally the first version of a software application that is feature-ready and released to testers, but rarely released to the public and frequently contains serious bugs\\"?","secenekler":["Beta version","Release Candidate (RC)","Alpha version","Final release","Software patch"],"dogruCevap":2,"explanation":"Doğru cevap Alpha version (alfa sürümü) terimidir. Soru kökündeki \'first version\', \'feature-ready\', \'released to testers\' ve \'contains serious bugs\' ifadeleri doğrudan alfa sürümünü niteleyen ayırt edici tetikleyicilerdir.","wrongExplanations":{"0":"Beta version; kurum içi testçilere değil, gerçek ortam geri bildirimi toplamak üzere halka (public) dağıtılan deneme sürümüdür.","1":"Release Candidate (RC); beta aşamasını başarıyla geçmiş ve nihai yayıma neredeyse hazır olan sürümdür.","3":"Final release; geliştirme döngüsünün son aşaması olup mağazalardan alınan veya indirilen gerçek programdır.","4":"Software patch; yazılımdaki mevcut hataları veya güvenlik açıklarını onarmak için sonradan sunulan güncelleme paketidir."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 02","metin":"Which software licensing model is defined as \\"proprietary software which can be distributed freely, but is limited by features and/or a time limit until a full version is purchased\\"?","secenekler":["Shareware","Freeware","Open source","Retail box","Public domain"],"dogruCevap":0,"explanation":"Doğru cevap Shareware terimidir. Soru kökündeki \'distributed freely\', \'limited by features and/or a time limit\' ve \'until a full version is purchased\' ifadeleri süreli veya kısıtlı özellik mantığıyla çalışan shareware modelini işaret eder.","wrongExplanations":{"1":"Freeware; geliştiricisi tarafından tamamen ücretsiz sunulan, herhangi bir kullanım süresi veya özellik kısıtlaması barındırmayan kapalı kaynaklı yazılımdır.","2":"Open source; kaynak kodları herkes tarafından görülebilen, incelenebilen ve özgürce değiştirilebilen yazılım modelidir.","3":"Retail box; yazılımın mağazalarda fiziksel kutu ambalajı içinde satılan ticari sürümüdür.","4":"Public domain; üzerinde hiçbir telif hakkı bulunmayan ve kamu malı haline gelmiş yazılımlardır."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 03","metin":"Which development stage describes software that \\"has passed the beta testing stage, is feature-complete, and is almost ready to be released to the public\\", often referred to internally by Apple as \\"the golden master\\"?","secenekler":["Alpha version","Beta version","Final release","Help file","Release Candidate (RC)"],"dogruCevap":4,"explanation":"Doğru cevap Release Candidate (RC) terimidir. Soru kökündeki \'passed the beta testing stage\', \'feature-complete\', \'almost ready to be released\' ve \'the golden master\' ifadeleri doğrudan sürüm adayını tanımlar.","wrongExplanations":{"0":"Alpha version; geliştirmenin en başında yer alan, bilinen hatalar barındıran ve halka kapalı olan ilk sürümdür.","1":"Beta version; sürüm adayından (RC) önce gelen ve geniş kitlelerce test edilen kararsız yapıdır.","2":"Final release; artık aday olmaktan çıkmış, kullanıcılara resmen dağıtılan veya satılan tamamlanmış nihai üründür.","3":"Help file; uygulamanın nasıl kullanılacağına dair yönergeler barındıran dokümantasyon dosyasıdır."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 04","metin":"Which of the following terms is defined as \\"a software update intended to fix bugs or security holes in a software release after end users complain about issues\\"?","secenekler":["Upgrade","Patch","Driver","Kernel","Format"],"dogruCevap":1,"explanation":"Doğru cevap Patch (yama) terimidir. \'Software update\', \'fix bugs or security holes\' ve \'after end users complain\' ifadeleri piyasaya çıkmış yazılımdaki arızaları gidermek için yayımlanan yamaları tanımlar.","wrongExplanations":{"0":"Upgrade; eski bir yazılımı veya donanımı bütünüyle daha yeni bir sürümle değiştirmektir.","2":"Driver; donanım bileşenlerinin işletim sistemiyle iletişim kurmasını sağlayan özel yazılımdır.","3":"Kernel; işletim sisteminin donanım ve yazılım arasındaki temel kaynak yönetimini yapan merkezi çekirdeğidir.","4":"Format; depolama birimindeki tüm verileri silerek sürücüyü yeni veri yazımına hazır hale getirme işlemidir."},"vurgulu":false},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 05","metin":"Which software distribution type represents \\"software distributed without cost by the developer which normally cannot be modified or sold without permission\\"?","secenekler":["Open source","Shareware","Retail software","Freeware","Firmware"],"dogruCevap":3,"explanation":"Doğru cevap Freeware terimidir. \'Without cost by the developer\' ve \'cannot be modified or sold without permission\' ifadeleri freeware yazılımların ücretsiz olduğunu ancak kaynak kodunun kapalı ve tescilli olduğunu açıklar.","wrongExplanations":{"0":"Open source; kaynak kodları incelenebilen, izin gerekmeksizin değiştirilebilen ve yeniden dağıtılabilen yazılımlardır.","1":"Shareware; belirli bir süre (trial) veya kısıtlı özellik sonrasında tam lisans alımı gerektiren deneme modelidir.","2":"Retail software; mağazalarda ticari lisans bedeli karşılığında kutulu veya lisans anahtarıyla satılan yazılımdır.","4":"Firmware; donanımların salt okunur belleklerine (ROM) yerleşik olarak yazılan temel kontrol yazılımıdır."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 06","metin":"Which version in the development process is defined as \\"a software program used for testing purposes before it is released to the public, distributed to gain free real-world testing and feedback\\"?","secenekler":["Alpha version","Beta version","Release Candidate (RC)","Device driver","Virtual Machine (VM)"],"dogruCevap":1,"explanation":"Doğru cevap Beta version terimidir. \'Testing purposes before it is released to the public\' ve \'real-world testing and feedback\' ifadeleri doğrudan beta test sürecine işaret eder.","wrongExplanations":{"0":"Alpha version; halka açık dağıtılmayan, yalnızca şirket içi test personeline sunulan ilk geliştirme yapısıdır.","2":"Release Candidate (RC); beta sürecini tamamlamış ve halka sunulmaya neredeyse hazır olan sürüm adayıdır.","3":"Device driver; bir çevre biriminin veya iç bileşenin işletim sistemi tarafından tanınmasını sağlayan sürücüdür.","4":"Virtual Machine (VM); fiziksel bir bilgisayarın kaynaklarını taklit ederek çalışan yazılımsal sanal ortamdır."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 07","metin":"Which of the following terms refers specifically to \\"a defect or logical flaw in code that causes a program to malfunction or produce incorrect results\\"?","secenekler":["Error","Crash","Abort","Bug","Patch"],"dogruCevap":3,"explanation":"Doğru cevap Bug terimidir. \'Defect or logical flaw in code\' ve \'malfunction\' ifadeleri doğrudan kaynak kodundaki teknik ve mantıksal kusurları tanımlar.","wrongExplanations":{"0":"Error; genellikle bir insan hatası veya sisteme uygunsuz girdi verilmesi sonucunda oluşan yanlış eylemdir.","1":"Crash; bir programın veya bilgisayar sisteminin beklenmeyen bir arıza nedeniyle tamamen çökmesidir.","2":"Abort; çalışan bir sürecin veya programın tamamlanmadan önce kasıtlı olarak zorla sonlandırılmasıdır.","4":"Patch; kod kusurlarını (bug) gidermek amacıyla yayımlanan düzeltme kodudur."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 08","metin":"Which operational term is formally defined in computing as \\"to deliberately end or terminate a program or process before its completion\\"?","secenekler":["Abort","Crash","Format","Upgrade","Launch"],"dogruCevap":0,"explanation":"Doğru cevap Abort terimidir. \'To deliberately end or terminate a program or process before its completion\' ifadesi bir işlemin bitmesini beklemeden durdurulmasını ifade eden temel teknik tanımdır.","wrongExplanations":{"1":"Crash; kasıtlı bir durdurma değil, sistemin beklenmedik bir arıza sonucu aniden çalışmayı durdurmasıdır.","2":"Format; diski sıfırlayarak dosya sistemi mimarisine hazır hale getirme işlemidir.","3":"Upgrade; mevcut donanım veya yazılımın daha üst ve yeni bir versiyonla değiştirilmesidir.","4":"Launch; bir uygulamanın veya sistem sürecinin çalıştırılması veya başlatılmasıdır."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 09","metin":"Which computing failure is specifically characterized as \\"a sudden and unexpected computer failure where an entire operating system or application ceases to function\\"?","secenekler":["Patch","Error","Abort","Debug","Crash"],"dogruCevap":4,"explanation":"Doğru cevap Crash (çökme) terimidir. Soru kökündeki \'sudden and unexpected computer failure\' ve \'ceases to function\' ifadeleri sistemin veya uygulamanın kilitlenip kapanmasını tanımlar.","wrongExplanations":{"0":"Patch; çökmelere yol açan açıkları ve hataları tamir etmek için geliştirilen yazılım yamasıdır.","1":"Error; yanlış işlem veya uygunsuz veri girişinden kaynaklanan genel hata durumudur.","2":"Abort; programın sistem veya kullanıcı tarafından planlı şekilde vaktinden önce sonlandırılmasıdır.","3":"Debug; kaynak kodundaki hataları tespit etme ve ayıklama sürecidir."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 10","metin":"Which process is formally defined as \\"to replace an older version of software or hardware with a newer version\\"?","secenekler":["Patch","Abort","Upgrade","Format","Debug"],"dogruCevap":2,"explanation":"Doğru cevap Upgrade (yükseltme) terimidir. \'To replace an older version of software or hardware with a newer version\' ifadesi doğrudan sürüm yükseltme eylemini tanımlar.","wrongExplanations":{"0":"Patch; mevcut sürümü değiştirmeden yalnızca tespit edilen spesifik hataları düzelten küçük kod ekidir.","1":"Abort; yürütülen bir komut dizisini tamamlanmadan önce durdurma işlemidir.","3":"Format; bir depolama aygıtındaki tüm verileri kalıcı olarak silip yeniden yapılandırmaktır.","4":"Debug; yazılım geliştirme safhasında kod kusurlarını bulup düzeltme aktivitesidir."},"vurgulu":false},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 11","metin":"Which of the following describes \\"a file containing instructions on how to use a certain program or feature, often providing users with shortcuts and documentation\\"?","secenekler":["Device driver","Release Candidate (RC)","Source code","Retail box","Help file"],"dogruCevap":4,"explanation":"Doğru cevap Help file (yardım dosyası) terimidir. \'A file containing instructions how to use a certain feature or program\' ve \'shortcuts\' ifadeleri yardım dosyalarının temel işlevini belirtir.","wrongExplanations":{"0":"Device driver; donanım parçalarını işletim sistemine tanıtan yazılım katmanıdır.","1":"Release Candidate (RC); beta sonrası dağıtıma sunulmaya hazır yazılım yapısıdır.","2":"Source code; programcılar tarafından insan tarafından okunabilir biçimde yazılmış programlama kodudur.","3":"Retail box; mağaza raflarında müşterilere sunulan fiziksel paketli yazılım ürünüdür."},"vurgulu":false},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 12","metin":"Which hardware category is defined as \\"an external computer add-on, such as a printer, external drive, or scanner; also commonly known as an accessory\\"?","secenekler":["Component","Peripheral","Operating System (OS)","Kernel","Application"],"dogruCevap":1,"explanation":"Doğru cevap Peripheral (çevre birimi) terimidir. \'External computer add-on\' ve \'accessory\' ifadeleri bilgisayar kasasının dışından bağlanan donanımları ifade eder.","wrongExplanations":{"0":"Component; anakart veya RAM gibi bilgisayar kasasının içinde (internal) yerleşik donanım parçalarıdır.","2":"Operating System (OS); donanım ve yazılım kaynaklarını yöneten ana sistem yazılımıdır.","3":"Kernel; işletim sisteminin tüm donanım etkileşimini yöneten en alt seviye çekirdeğidir.","4":"Application; kullanıcıların verimlilik ve iş üretimi sağlamak için çalıştırdığı programdır."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 13","metin":"Which hardware term is specifically defined as \\"any hardware device or electronic part that is internal to the computer case, such as the motherboard or RAM\\"?","secenekler":["Peripheral","Freeware","Shareware","Component","Application"],"dogruCevap":3,"explanation":"Doğru cevap Component (bileşen) terimidir. \'Device internal to the computer case\', \'motherboard\' ve \'RAM\' ifadeleri doğrudan dahili donanım bileşenlerini işaret eder.","wrongExplanations":{"0":"Peripheral; bilgisayara dışarıdan kablo veya kablosuz bağlanan harici donanım eklentisidir.","1":"Freeware; tamamen ücretsiz ve telif hakları saklı yazılım lisanslama modelidir.","2":"Shareware; belirli süre veya özellik kısıtlamasıyla sunulan deneme sürümü yazılımıdır.","4":"Application; donanım üzerinde belirli görevleri gerçekleştiren son kullanıcı yazılımıdır."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 14","metin":"Which terminology item represents \\"an incorrect action or unintended condition attributable to human mistakes, improper operation, or incorrect data input\\"?","secenekler":["Error","Bug","Crash","Abort","Patch"],"dogruCevap":0,"explanation":"Doğru cevap Error (hata) terimidir. \'Incorrect action attributable to human mistakes\' ifadesi, kodlama kusuru olan bug teriminden farklı olarak insan ve operasyon kaynaklı yanlışlıkları ifade eder.","wrongExplanations":{"1":"Bug; insan kullanımından ziyade kodun yazımındaki mantıksal kusur ve açıklardır.","2":"Crash; işletim sisteminin ya da programın tamamen yanıt vermez hale gelip çökmesidir.","3":"Abort; bir görevin sonuna kadar beklenmeden manuel ya da otomatik şekilde kesilmesidir.","4":"Patch; kod hatalarını gidermek amacıyla yayınlanan yazılım onarım paketidir."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 15","metin":"Which software licensing classification refers to software whose source code is kept secret as private property, meaning it cannot be modified or redistributed without vendor permission?","secenekler":["Open source","Public domain","Proprietary software","Freeware utility","Community edition"],"dogruCevap":2,"explanation":"Doğru cevap Proprietary software (tescilli/mülk yazılım) terimidir. \'Private property\', \'source code kept secret\' ve \'cannot be modified or redistributed without permission\' ifadeleri mülkiyeti şirkete ait kapalı modelleri niteler.","wrongExplanations":{"0":"Open source; kaynak kodları kamuya açık olan ve üzerinde serbestçe değişiklik yapılabilen yazılımlardır.","1":"Public domain; yasal mülkiyeti ve telifi bulunmayan, tamamen kamu kullanımına terk edilmiş yazılımlardır.","3":"Freeware utility; tescilli yazılımın ücretsiz dağıtılan alt türüdür; ancak üst kavram mülkiyet odaklı proprietary sınıfıdır.","4":"Community edition; genellikle açık kaynak toplulukları tarafından geliştirilen veya paylaşılan sürümdür."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 16","metin":"Which stage in the software development life cycle represents \\"the final commercial program that end users purchase in retail shops or download from official distribution platforms\\"?","secenekler":["Alpha version","Beta version","Release Candidate (RC)","Final release","Proof of concept"],"dogruCevap":3,"explanation":"Doğru cevap Final release (nihai sürüm) terimidir. Soru kökündeki \'final commercial program\', \'purchase in retail shops\' ve \'download from official distribution platforms\' ifadeleri tamamlanmış nihai ürünü gösterir.","wrongExplanations":{"0":"Alpha version; şirket içinde test edilen ve henüz son kullanıcıya satılmayan ilk kararsız sürümdür.","1":"Beta version; geri bildirim toplamak amacıyla genel halka sunulan test sürümüdür.","2":"Release Candidate (RC); nihai dağıtımdan bir önceki kontrol ve doğrulama aşamasıdır.","4":"Proof of concept; fikrin teknik olarak çalışabilirliğini kanıtlamak için yapılan erken dönem prototipidir."},"vurgulu":false},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 17","metin":"Which software category is formally defined as \\"a program designed to make users more productive and get work done faster, performing specific tasks such as writing letters or processing data\\"?","secenekler":["Operating System (OS)","Device driver","Application","Central Processing Unit (CPU)","Virtual Machine (VM)"],"dogruCevap":2,"explanation":"Doğru cevap Application (uygulama) terimidir. \'Make users more productive\', \'get work done faster\' ve \'performing specific tasks\' ifadeleri uygulama yazılımlarının temel amacını açıklar.","wrongExplanations":{"0":"Operating System (OS); bilgisayarın tüm donanım ve yazılım kaynaklarını yöneten temel sistem platformudur.","1":"Device driver; çevre birimlerinin bilgisayarla haberleşmesini sağlayan düşük seviyeli sürücüdür.","3":"Central Processing Unit (CPU); bilgisayardaki komutları işleyen merkezi donanım birimidir.","4":"Virtual Machine (VM); donanım kaynaklarını sanallaştırarak başka bir işletim sistemi çalıştırmayı sağlayan yapıdır."},"vurgulu":false},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 18","metin":"Which historical distribution method refers to software that is \\"traditionally packaged in physical containers with printed manuals and bought directly from physical retail stores\\"?","secenekler":["Retail box","Freeware","Shareware","Help file","Patch"],"dogruCevap":0,"explanation":"Doğru cevap Retail box (perakende kutusu) terimidir. \'Packaged in physical containers\' ve \'bought directly from physical retail stores\' ifadeleri kutulu fiziksel yazılım dağıtımını niteler.","wrongExplanations":{"1":"Freeware; genellikle internetten indirilen tamamen ücretsiz dijital yazılım modelidir.","2":"Shareware; internet üzerinden serbestçe indirilebilen kısıtlı deneme sürümüdür.","3":"Help file; programın kullanımı hakkında dijital yönergeler içeren dosyadır.","4":"Patch; mevcut yazılımdaki eksikleri ve açıkları onaran indirilebilir güncellemedir."},"vurgulu":false},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 19","metin":"Which software distribution model provides software where \\"the original source code is made freely available and may be redistributed and modified by any user or developer\\"?","secenekler":["Proprietary software","Open source software","Retail box software","Shareware package","Closed source software"],"dogruCevap":1,"explanation":"Doğru cevap Open source software (açık kaynak yazılım) terimidir. \'Original source code is made freely available\' ve \'redistributed and modified\' ifadeleri açık kaynak felsefesinin temel unsurlarıdır.","wrongExplanations":{"0":"Proprietary software; kaynak kodu gizli tutulan ve üzerinde değişiklik yapılması yasak olan yazılımdır.","2":"Retail box software; ticari amaçla kutulu satılan kapalı kaynaklı yazılımdır.","3":"Shareware package; kaynak kodu kapalı olan ve süre/özellik kısıtıyla dağıtılan deneme yazılımıdır.","4":"Closed source software; kaynak kodu kamuya kapalı olan tescilli yazılımların genel adıdır."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Software Applications","baslik":"Soru 20","metin":"In early software development, especially during internal alpha testing, an initial build created to demonstrate that a design concept or technical approach is feasible is known as a:","secenekler":["Release Candidate (RC)","Final release","Golden master","Retail box","Proof of concept"],"dogruCevap":4,"explanation":"Doğru cevap Proof of concept (kavram kanıtı) terimidir. \'Demonstrate that a design concept or technical approach is feasible\' ve \'early software development / alpha testing\' ifadeleri bu terimi doğrudan işaret eder.","wrongExplanations":{"0":"Release Candidate (RC); uygulanabilirliği çoktan kanıtlanmış ve yayına çıkmaya hazır son aşama sürümüdür.","1":"Final release; kullanıcılara satılmak üzere tamamlanmış gerçek ticari üründür.","2":"Golden master; sürüm adayının (RC) Apple terminolojisindeki karşılığı olup nihai üretim kalıbıdır.","3":"Retail box; mağazalarda satılan kutulu ürün paketleme biçimidir."},"vurgulu":false}]'))},60505,e=>{e.v(JSON.parse('[{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 01","metin":"Which executive job position is formally defined as being \\"responsible for internal processes and practices\\" and \\"normally has a stronger business administration background than technical background\\"?","secenekler":["Chief Technical Officer (CTO)","Chief Information Officer (CIO)","Enterprise Architect","IT Security Manager","Project Manager (PM)"],"dogruCevap":1,"explanation":"Doğru cevap Chief Information Officer (CIO) pozisyonudur. Soru kökündeki \'internal processes and practices\' (iç süreçler ve kurumsal uygulamalar) ile işletme/yönetim arka planının teknik yönünden daha güçlü olması (\'stronger business administration background than technical background\') doğrudan CIO görev tanımını verir.","wrongExplanations":{"0":"Chief Technical Officer (CTO); şirketteki tüm bilimsel ve teknolojik konulardan sorumludur ve yönetimden ziyade güçlü bir teknik geçmişe sahiptir.","2":"Enterprise Architect; kurumsal düzeyde iş gereksinimlerini karşılayacak genel BT altyapısını tasarlayan mimardır, C-level bir icra kurulu başkanı değildir.","3":"IT Security Manager; kablosuz ağlar, sunucular ve VPN gibi altyapıların güvenlik politikalarını belirleyen operasyonel yöneticidir.","4":"Project Manager (PM); projeleri bütçesine ve teslim tarihine uygun şekilde yürütmekle yükümlü olan ve paydaşlarla geliştiriciler arasında köprü kuran pozisyondur."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 02","metin":"Which C-level executive role is described as being \\"responsible for all scientific and technological issues related to a company\\" and typically possesses a \\"strong technical and somewhat less strong management background\\"?","secenekler":["Chief Information Officer (CIO)","Information Architect","Chief Technical Officer (CTO)","Enterprise Architect","Database Administrator (DBA)"],"dogruCevap":2,"explanation":"Doğru cevap Chief Technical Officer (CTO) pozisyonudur. Soru kökündeki \'responsible for all scientific and technological issues\' ve \'strong technical and somewhat less strong management background\' ifadeleri CTO unvanının ayırt edici nitelikleridir.","wrongExplanations":{"0":"Chief Information Officer (CIO); teknik yönden ziyade işletme/yönetim ağırlıklı bir profile sahiptir ve kurum içi süreçler ile bütçeyi yönetir.","1":"Information Architect; karmaşık veri yapılarının son kullanıcılar tarafından rahat gezilebilmesini sağlayan tasarım rolüdür.","3":"Enterprise Architect; şirketin iş hedeflerine uygun BT mimarisini kurgulayan uzman pozisyondur.","4":"Database Administrator (DBA); ilişkisel veritabanlarının bakımından ve kullanıcı erişim haklarından sorumlu teknik uzmandır."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 03","metin":"Which IT role is defined as \\"acting as a bridge between upper management and IT\\" and is responsible for encouraging \\"personal development in IT staff\\"?","secenekler":["IT Manager","Project Manager (PM)","Business Analyst (BA)","Network Administrator","Enterprise Architect"],"dogruCevap":0,"explanation":"Doğru cevap IT Manager unvanıdır. Üst yönetim ile BT kadrosu arasında köprü vazifesi görmek (\'bridge between upper management and IT\'), personelin amiri olmak ve çalışanların kişisel gelişimini desteklemek (\'encourages personal development in IT staff\') bu pozisyonun temel tanımıdır.","wrongExplanations":{"1":"Project Manager (PM); üst yönetim ile IT kadrosu arasında değil, yazılım geliştiriciler ile paydaşlar (stakeholders) arasında köprüdür.","2":"Business Analyst (BA); iş kurallarını analiz edip teknik sistemlere aktaran köprü rolüdür, personel amiri değildir.","3":"Network Administrator; ağ yönlendirme, TCP/IP ve Cisco cihazlarının yapılandırmasından sorumludur.","4":"Enterprise Architect; kurumsal BT yapılarını ve teknoloji platformlarını tasarlayan mimarlık rolüdür."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 04","metin":"A professional responsible for \\"organizing and delivering a project on time and on budget\\" who frequently \\"acts as a bridge between developers and stake-holders\\" is designated as a:","secenekler":["Business Analyst (BA)","IT Support Engineer","Enterprise Architect","Project Manager (PM)","Database Administrator (DBA)"],"dogruCevap":3,"explanation":"Doğru cevap Project Manager (PM) rolüdür. Soru kökündeki \'on time and on budget\' (zamanında ve bütçesinde) teslimat hedefi ve \'bridge between developers and stake-holders\' (geliştiriciler ile paydaşlar arası köprü) ifadeleri PM pozisyonunu tanımlayan tetikleyicilerdir.","wrongExplanations":{"0":"Business Analyst (BA); proje bütçesinden ve teslimatından ziyade iş gereksinimlerinin teknik ekiplere aktarılmasıyla ilgilenir.","1":"IT Support Engineer; son kullanıcılara donanım, yazılım ve temel ağ sorunlarında anlık destek verir.","2":"Enterprise Architect; şirketin iş hedeflerini destekleyecek büyük ölçekli kurumsal BT mimarisini çizer.","4":"Database Administrator (DBA); ilişkisel veritabanlarının erişim yetkilerini ve performansını yönetir."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 05","metin":"Which role is specifically tasked with \\"making complex data structures easy to understand and navigate\\" and often prepares \\"wireframes and a glossary of target vocabulary\\" during the initial phases of software development?","secenekler":["Graphic Designer","Database Developer","Technical Writer","Enterprise Architect","Information Architect"],"dogruCevap":4,"explanation":"Doğru cevap Information Architect rolüdür. \'Making complex data structures easy to understand and navigate\' (karmaşık veri yapılarını anlaşılır ve gezinmesi kolay kılmak) ve projelerin başlangıcında \'wireframes\' (tel kafes tasarımlar) hazırlamak Information Architect\'in temel görevidir.","wrongExplanations":{"0":"Graphic Designer; ön yüz için tipografi, renk eşleştirme ve görsel maketler (mock-ups) hazırlar.","1":"Database Developer; veritabanı tablolarını kodlar, 3NF optimizasyonu ve refactoring yapar.","2":"Technical Writer; çevrimiçi yardım, kullanıcı kılavuzları ve şartnameler gibi yazılı dokümanları üretir.","3":"Enterprise Architect; veri yapılarının navigasyonundan ziyade tüm şirketin kurumsal BT altyapı ihtiyaçlarını modeller."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 06","metin":"Which high-level specialist is responsible for \\"understanding a business\'s overall needs and then designing an IT structure to support it\\"?","secenekler":["Network Administrator","Enterprise Architect","Information Architect","Software Developer","Business Analyst (BA)"],"dogruCevap":1,"explanation":"Doğru cevap Enterprise Architect rolüdür. Soru kökündeki \'understanding a business\'s overall needs\' (işletmenin genel ihtiyaçlarını anlama) ve \'designing an IT structure to support it\' (bunu destekleyecek BT yapısını tasarlama) ifadeleri kurumsal mimarın resmi tanımıdır.","wrongExplanations":{"0":"Network Administrator; yönlendiriciler, anahtarlar ve ağ kablolaması gibi yerel/geniş ağ altyapısının sürekliliğini sağlar.","2":"Information Architect; karmaşık veri yapılarının son kullanıcı arayüzünde gezinilebilir ve anlaşılır olmasını sağlar.","3":"Software Developer; verilen programlama görevlerine ilişkin bilgi toplayıp kodlama işlemlerini yürütür.","4":"Business Analyst (BA); iş kurallarını yorumlayıp teknik sistemlere aktarır ancak kurumsal IT mimarisini tasarlamaz."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 07","metin":"An IT specialist who is primarily in charge of \\"managing and maintaining relational databases and their access rights\\" is known as a:","secenekler":["Database Administrator (DBA)","Database Developer","Software Developer","Network Administrator","System Administrator"],"dogruCevap":0,"explanation":"Doğru cevap Database Administrator (DBA) unvanıdır. İlişkisel veritabanlarını yönetmek, bakımını yapmak ve özellikle erişim izinlerini denetlemek (\'managing and maintaining relational databases and their access rights\') DBA rolünü Database Developer\'dan ayıran en temel kıstastır.","wrongExplanations":{"1":"Database Developer; veritabanını yönetmek ve erişim haklarını kısıtlamaktan ziyade veritabanını programlamak, şemaları optimize etmek ve 3NF standardına getirmekle ilgilenir.","2":"Software Developer; uygulama katmanında yazılım kodlaması yapar.","3":"Network Administrator; veritabanı seviyesinde değil, kurumsal ağ iletişimi ve donanımları seviyesinde çalışır.","4":"System Administrator; sunucu işletim sistemleri ve genel BT altyapı erişimlerinden sorumludur."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 08","metin":"Which technical professional is formally responsible for \\"programming and optimizing databases\\", including tasks such as schema refactoring to achieve Third Normal Form (3NF)?","secenekler":["Database Administrator (DBA)","Information Architect","Database Developer","Enterprise Architect","Business Analyst (BA)"],"dogruCevap":2,"explanation":"Doğru cevap Database Developer rolüdür. Veritabanının programlanması, optimizasyonu (\'programming and optimizing databases\') ve Third Normal Form (3NF) elde etmek için yeniden yapılandırılması (refactoring) bu pozisyonun ayırt edici niteliğidir.","wrongExplanations":{"0":"Database Administrator (DBA); optimizasyondan ziyade veritabanı erişim hakları (access rights), felaket kurtarma ve bakım operasyonlarıyla ilgilenir.","1":"Information Architect; veri tabanının fiziksel şemasıyla değil, son kullanıcının veriyi anlama ve gezinme ergonomisiyle ilgilenir.","3":"Enterprise Architect; kurumsal ölçekteki tüm BT mimarisini planlar, veritabanı normalizasyonu kodlamaz.","4":"Business Analyst (BA); iş kurallarını sistem gereksinimlerine dönüştürür, veritabanı programlaması yapmaz."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 09","metin":"Which job position is defined as being responsible for the \\"interpretation of business rules and delivering them to technical systems\\"?","secenekler":["Technical Writer","Graphic Designer","Project Manager (PM)","IT Support Engineer","Business Analyst (BA)"],"dogruCevap":4,"explanation":"Doğru cevap Business Analyst (BA) pozisyonudur. Soru kökündeki \'interpretation of business rules\' (iş kurallarının yorumlanması) ve \'delivering them to technical systems\' (bunların teknik sistemlere aktarılması) ifadeleri iş analistinin anahtar tanımıdır.","wrongExplanations":{"0":"Technical Writer; teknik sistemlerin kullanım kılavuzlarını ve dokümantasyonunu hazırlar.","1":"Graphic Designer; sistemin ön yüzü için görsel, tipografi ve taslak modeller üretir.","2":"Project Manager (PM); projenin zaman ve bütçe kısıtları dahilinde teslim edilmesini koordine eder.","3":"IT Support Engineer; son kullanıcıların donanım ve yazılım arızalarını gidermekle yükümlüdür."},"vurgulu":false},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 10","metin":"A professional responsible for the \\"creation of images, typography, mock-ups for an organization\'s front end systems\\" and who normally works under an Art Director is a:","secenekler":["Information Architect","Software Developer","Technical Writer","Graphic Designer","Enterprise Architect"],"dogruCevap":3,"explanation":"Doğru cevap Graphic Designer rolüdür. Soru metnindeki \'creation of images, typography, mock-ups\' (görseller, tipografi ve maketlerin oluşturulması) ve \'works under an Art Director\' (Sanat Yönetmeni altında çalışma) ifadeleri grafik tasarımcının resmî tanımıdır.","wrongExplanations":{"0":"Information Architect; görsel estetikten ziyade veri yapılarının mantıksal mimarisi ve wireframe tasarımlarıyla ilgilenir.","1":"Software Developer; uygulamanın mantıksal kodunu ve işlevsel altyapısını programlar.","2":"Technical Writer; metinsel belgeler, beyaz bültenler ve kullanıcı dokümanları üretir.","4":"Enterprise Architect; kurumsal çapta BT sistem entegrasyonlarını ve teknoloji standartlarını tasarlar."},"vurgulu":false},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 11","metin":"Which role is responsible for the \\"creation and maintenance of documentation relating to an IT project including online help, user guides, white papers, and design specifications\\"?","secenekler":["Technical Writer","Business Analyst (BA)","Software Tester","Information Architect","Graphic Designer"],"dogruCevap":0,"explanation":"Doğru cevap Technical Writer rolüdür. Tanımda yer alan \'online help\' (çevrimiçi yardım), \'user guides\' (kullanıcı kılavuzları), \'white papers\' (beyaz bültenler/teknik raporlar) ve \'design specifications\' (tasarım şartnameleri) hazırlama görevi teknik yazara aittir.","wrongExplanations":{"1":"Business Analyst (BA); sistem gereksinimlerini ve iş kurallarını analiz eder, proje yardım kılavuzları yazmaz.","2":"Software Tester; yazılımın kalite standartlarına uygunluğunu denetler ve hataları belgeler.","3":"Information Architect; veri navigasyon şemaları ve bilgi mimarisi yapılandırır.","4":"Graphic Designer; görsel arayüz öğeleri, tipografi ve grafik maketleri üretir."},"vurgulu":false},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 12","metin":"Which IT professional is responsible for the \\"maintenance of all aspects of a computer network\\" and typically specializes in \\"TCP/IP, Linux, and related routing technology such as Cisco\\"?","secenekler":["IT Support Engineer","Network Administrator","System Administrator","IT Security Manager","Database Developer"],"dogruCevap":1,"explanation":"Doğru cevap Network Administrator rolüdür. \'Maintenance of all aspects of a computer network\' (bilgisayar ağının tüm yönleriyle bakımı) ve \'TCP/IP, Linux, routing technology such as Cisco\' (Cisco gibi yönlendirme teknolojileri ve ağ protokolleri) ağ yöneticisinin anahtar uzmanlık alanlarıdır.","wrongExplanations":{"0":"IT Support Engineer; son kullanıcıların masaüstü bilgisayarlarındaki donanım ve yazılım arızalarını çözer.","2":"System Administrator; ağ yönlendirmesinden ziyade tüm sunucu işletim sistemleri ve kurumsal sistem erişimlerinden sorumludur.","3":"IT Security Manager; ağ güvenliği, VPN ve Wi-Fi en iyi uygulamalarını (best practices) ve güvenlik politikalarını belirler.","4":"Database Developer; veritabanı tablolarını ve sorgularını optimize eder."},"vurgulu":false},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 13","metin":"Which position is in charge of providing \\"on-demand support for end users including: fixing hardware, installing software, and troubleshooting minor network issues\\"?","secenekler":["System Administrator","Network Administrator","Information Architect","IT Security Manager","IT Support Engineer"],"dogruCevap":4,"explanation":"Doğru cevap IT Support Engineer rolüdür. Son kullanıcılara anlık destek sunmak (\'on-demand support for end users\'), donanım tamiri (\'fixing hardware\') ve yazılım yükleme (\'installing software\') IT destek mühendisinin doğrudan görev alanıdır.","wrongExplanations":{"0":"System Administrator; doğrudan son kullanıcı donanım arızalarından ziyade kurumsal sunucu altyapısını ve ana sistemleri yönetir.","1":"Network Administrator; kurumsal ağ altyapısı, switchler ve yönlendiricilerin genel bakımından sorumludur.","2":"Information Architect; yazılım arayüzlerinde veri yapılarının mimarisini kurar.","3":"IT Security Manager; güvenlik kurallarını, şifreleme politikalarını ve sistem savunmasını koordine eder."},"vurgulu":false},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 14","metin":"Which management role is responsible for \\"setting best practices for securing wi-fi networks, servers, backups, laptops, and VPNs\\"?","secenekler":["Network Administrator","Chief Technical Officer (CTO)","IT Security Manager","Database Administrator (DBA)","IT Support Engineer"],"dogruCevap":2,"explanation":"Doğru cevap IT Security Manager rolüdür. Wi-Fi ağları, sunucular, yedekleme mekanizmaları ve VPN altyapısının güvenliğini sağlamaya yönelik en iyi uygulamaları belirleme sorumluluğu (\'setting best practices for securing...\') BT güvenlik yöneticisine aittir.","wrongExplanations":{"0":"Network Administrator; güvenlik stratejisinden ziyade ağ donanımlarının yönlendirme ve süreklilik bakımını icra eder.","1":"Chief Technical Officer (CTO); şirketin en üst düzey teknoloji yöneticisidir ve tüm bilimsel/teknolojik politikalardan sorumludur.","3":"Database Administrator (DBA); ilişkisel veritabanlarının yönetimi ve veritabanı erişim haklarıyla ilgilenir.","4":"IT Support Engineer; son kullanıcıların donanım ve yazılım problemlerini yerinde veya uzaktan çözer."},"vurgulu":false},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 15","metin":"A person whose responsibilities include \\"ensuring appropriate performance for a software project and organizing and instructing testers\\" holds the title of:","secenekler":["Project Manager (PM)","IT Security Manager","Software Developer","Quality Assurance Manager (QA Manager)","Chief Information Officer (CIO)"],"dogruCevap":3,"explanation":"Doğru cevap Quality Assurance Manager (QA Manager) unvanıdır. Yazılımın performans standartlarını garanti altına almak ve test personelini organize edip yönlendirmek (\'organizing and instructing testers\') QA Manager rolünün resmi tanımıdır.","wrongExplanations":{"0":"Project Manager (PM); projeyi bütçe ve takvim dahilinde yönetir, doğrudan test uzmanlarının teknik talimat amiri değildir.","1":"IT Security Manager; siber güvenlik protokolleri, Wi-Fi ve VPN politikaları ile ilgilenir.","2":"Software Developer; programlama görevlerini yerine getirir, test ekibini yönetmez.","4":"Chief Information Officer (CIO); şirket içi süreçlerden ve BT bütçesinden sorumlu tepe yöneticidir."},"vurgulu":false},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 16","metin":"Which specialist is specifically responsible for \\"ensuring that a software project meets established quality guidelines\\" and documenting bugs?","secenekler":["Software Tester","Technical Writer","Information Architect","Graphic Designer","Database Developer"],"dogruCevap":0,"explanation":"Doğru cevap Software Tester rolüdür. Yazılımın belirlenen kalite kurallarına uygunluğunu doğrulamak (\'meets established quality guidelines\') ve yazılım hatalarını (bugs) tespit edip belgelemek yazılım test uzmanının asli görevidir.","wrongExplanations":{"1":"Technical Writer; yazılımın teknik dokümantasyonunu ve kullanıcı el kitaplarını kaleme alır.","2":"Information Architect; karmaşık veri yapılarının kullanıcılar için gezinilebilir olmasını sağlar.","3":"Graphic Designer; sistemlerin görsel unsurlarını ve arayüz maketlerini çizer.","4":"Database Developer; veritabanı tablolarını oluşturur ve sorguları optimize eder."},"vurgulu":false},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 17","metin":"A position formally defined as being responsible for \\"gathering information around a programming task and performing it\\" is a:","secenekler":["Business Analyst (BA)","Technical Writer","Software Developer","Software Tester","Enterprise Architect"],"dogruCevap":2,"explanation":"Doğru cevap Software Developer rolüdür. Kendisine iletilen programlama görevi çerçevesinde bilgi toplamak ve bu kodlama görevini yürütmek (\'gathering information around a programming task and performing it\') yazılım geliştiricinin resmi tanımıdır.","wrongExplanations":{"0":"Business Analyst (BA); iş kurallarını analiz ederek teknik sisteme aktarır, doğrudan programlama görevini icra etmez.","1":"Technical Writer; yazılım projelerinin tasarım şartnamelerini ve belgelerini yazar.","3":"Software Tester; yazılan kodun kalite yönergelerine uygunluğunu test eder.","4":"Enterprise Architect; şirketin genel iş hedeflerine yönelik üst düzey BT mimarisini planlar."},"vurgulu":false},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 18","metin":"In an IT work environment, what term describes the destructive behavior where an individual harbors negative thoughts about a person or idea and then proceeds with \\"talking badly behind someone\'s back (when that person is not around)\\"?","secenekler":["Authoritarian behavior","Passive-aggressive behavior","Conflict-avoidant behavior","Direct-aggressive behavior","Counter-productive behavior"],"dogruCevap":1,"explanation":"Doğru cevap Passive-aggressive behavior (Pasif-agresif davranış) kavramıdır. Bir kişi veya fikir hakkında olumsuz düşünüp, o kişi ortamda yokken arkasından konuşmak (\'talking badly behind someone\'s back when that person is not around\') bu kavramın birebir karşılığıdır.","wrongExplanations":{"0":"Authoritarian behavior (Otoriter davranış); gücü tek elde toplayarak başkalarının fikirlerini baskılama tutumudur.","2":"Conflict-avoidant behavior (Çatışmadan kaçınan davranış); sorunları konuşmaktan veya yüzleşmekten tamamen geri durma durumudur.","3":"Direct-aggressive behavior (Doğrudan agresif davranış); olumsuz düşünceleri kişinin yüzüne açıkça ve sert şekilde yansıtma eylemidir.","4":"Counter-productive behavior (Üretkenlik karşıtı davranış); şirket performansına zarar veren genel iş yeri eylemlerini ifade eden şemsiye bir terimdir."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 19","metin":"According to professional career hierarchies in software engineering, developers typically progress through which sequence of hierarchical levels from entry to leadership?","secenekler":["Associate, Executive, Principal","Trainee, Operational, Director","Novice, Intermediate, Supervisor","Junior, Senior, Lead","Specialist, Expert, Officer"],"dogruCevap":3,"explanation":"Doğru cevap Junior, Senior, Lead sıralamasıdır. Yazılım mühendisliği kariyer kademelerinde başlangıç seviyesi \'junior\', deneyimli seviye \'senior\' ve ekip yöneticisi/lider seviyesi ise \'lead\' unvanıyla ifade edilir.","wrongExplanations":{"0":"Associate, Executive, Principal; kurumsal yönetim ve danışmanlık kademelerinde kullanılan farklı bir unvan hiyerarşisidir.","1":"Trainee, Operational, Director; genel operasyonel şirket unvanlarıdır, geliştirici rollerinin standardı değildir.","2":"Novice, Intermediate, Supervisor; genel yetkinlik düzeyleri olup IT geliştirici pozisyon kademelerini temsil etmez.","4":"Specialist, Expert, Officer; teknik uzmanlık veya kamu kadrolarında görülen farklı bir sınıflandırmadır."},"vurgulu":false},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 20","metin":"To increase professional value within an IT organization, which of the following agile role credentials is explicitly recommended for individuals aspiring to manage software team workflows?","secenekler":["Systems Analyst","Security Specialist","Database Manager","Technical Writer","ScrumMaster"],"dogruCevap":4,"explanation":"Doğru cevap ScrumMaster unvanıdır. Çevik (Agile) proje süreçlerini yönetmek ve yazılım ekiplerinin verimini artırmak için bireylerin bir proje yöneticisi veya \'ScrumMaster\' olmak üzere sertifikasyon ve eğitim alması gerektiği belirtilmektedir.","wrongExplanations":{"0":"Systems Analyst; sistem analizlerini ve gereksinim modellemelerini yapan teknik roldür, çevik proje liderliği unvanı değildir.","1":"Security Specialist; siber güvenlik protokollerini uygulayan teknik uzmandır.","2":"Database Manager; veri varlıklarını ve veritabanı altyapılarını yöneten idarecidir.","3":"Technical Writer; teknik belgeleri ve kullanıcı dokümantasyonunu hazırlayan uzmanlıktır."},"vurgulu":false}]'))},47711,e=>{e.v(JSON.parse('[{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 01","metin":"Which of the following statements technically describes the fundamental distinction between the \\"Internet\\" and the \\"World Wide Web (WWW)\\"?","secenekler":["The Internet is a global network, whereas the Web is an application running on it.","The Web represents the physical network, whereas the Internet handles page markup.","The Internet was built solely for commerce, whereas the Web manages defense routing.","The Web is an outdated dial-up standard, whereas the Internet is a client browser.","Both terms represent completely identical systems and function as exact synonyms."],"dogruCevap":0,"explanation":"Doğru cevap ilk seçenektir. İnternet dünyadaki en büyük fiziksel ağ altyapısı (the biggest network in the world) iken, World Wide Web bu ağ üzerinde çalışan yazılım, protokol ve multimedya uygulama katmanıdır (an application that runs on the Internet).","wrongExplanations":{"1":"Fiziksel ağ altyapısını temsil eden Web değil, İnternet\'tir; işaretleme dillerini kullanan ise Web katmanıdır.","2":"İnternet savunma ve askeri amaçlarla (ARPANET) ortaya çıkmış, ticari kullanım ve e-ticaret sonradan Web ile yaygınlaşmıştır.","3":"World Wide Web bir çevirmeli ağ (dial-up) standardı değil, köprü metin tabanlı küresel bir bilgi sistemidir.","4":"İnternet ile Web eşanlamlı değildir; biri fiziksel ağ altyapısı, diğeri onun üzerinde koşan servis ve protokoller bütünüdür."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 02","metin":"Which networking milestone is formally defined as \\"developed by the US military for defense purposes, this was the first global network with packet switching\\"?","secenekler":["CompuServe Information Service","Advanced Research Projects Agency Network (ARPANET)","World Wide Web Consortium (W3C)","French Minitel Terminal System","Bulletin Board System (BBS)"],"dogruCevap":1,"explanation":"Doğru cevap ARPANET\'tir. Soru kökündeki \'US military\', \'defense purposes\' ve \'first global network with packet switching\' ifadeleri doğrudan ARPANET\'i niteleyen teknik tetikleyicilerdir.","wrongExplanations":{"0":"CompuServe; 1980\'lerde meraklıların kullandığı ilk ticari çevrimiçi hizmet sağlayıcılarından biridir, askeri bir ağ değildir.","2":"W3C; Web standartlarını belirlemek amacıyla 1994 yılında Tim Berners-Lee tarafından kurulan konsorsiyumdur.","3":"Minitel; Fransa\'da geliştirilen ancak dünya geneline yayılamayan erken dönem bir terminal ağıdır.","4":"BBS; modemler aracılığıyla çevirmeli bağlantı sağlanan bağımsız erken dönem yerel bülten panolarıdır."},"vurgulu":false},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 03","metin":"Which network operation is formally defined as \\"the transfer of a file or files from a remote computer to the user\'s computer\\"?","secenekler":["Upload","Streaming","Download","Browsing","Hyperlink"],"dogruCevap":2,"explanation":"Doğru cevap Download (indirme) terimidir. Soru kökündeki \'from a remote computer to the user\'s computer\' (uzak bilgisayardan/sunucudan kullanıcının yerel bilgisayarına) yön ifadesi Download işleminin temel tanımıdır.","wrongExplanations":{"0":"Upload (yükleme); dosyanın yerel bilgisayardan uzak bir bilgisayara/sunucuya (local to remote) aktarılmasıdır.","1":"Streaming; verilerin yerel diske kaydedilmeden gerçek zamanlı olarak sunucudan oynatılması sürecidir.","3":"Browsing; web sayfaları arasında gezinme ve içerikleri tarayıcı aracılığıyla inceleme eylemidir.","4":"Hyperlink; belgeler arasında geçiş sağlayan tıklanabilir çapraz referans bağlantısıdır."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 04","metin":"Which operational term describes the process to \\"transfer a file from a local computer to a remote computer\\"?","secenekler":["Download","Bookmark","Hyperlink","Upload","Domain"],"dogruCevap":3,"explanation":"Doğru cevap Upload (yükleme) terimidir. Dosyanın kullanıcının yerel sisteminden uzak bir sunucuya (\'from a local computer to a remote computer\') gönderilmesi Upload işlemi olarak tanımlanır.","wrongExplanations":{"0":"Download; dosyanın uzaktaki bir sunucudan yerel bilgisayara aktarılmasıdır.","1":"Bookmark; web tarayıcılarında sık ziyaret edilen sitelerin kaydedildiği yer imidir.","2":"Hyperlink; tıklandığında ilgili kaynağı getiren metin veya görsel bağlantısıdır.","4":"Domain; bir web sitesini internet üzerinde benzersiz şekilde tanımlayan adrestir."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 05","metin":"Which concept is formally defined as \\"any electronic cross-referencing document first prophesized by Vannevar Bush in 1945\\"?","secenekler":["Uniform Resource Locator (URL)","Hypertext Markup Language (HTML)","World Wide Web Consortium (W3C)","Bulletin Board System (BBS)","Hypertext"],"dogruCevap":4,"explanation":"Doğru cevap Hypertext (köprü metin) terimidir. Soru kökündeki \'electronic cross-referencing document\' ve \'first prophesized by Vannevar Bush in 1945\' ifadeleri doğrudan Hypertext kavramını işaret eden tetikleyicilerdir.","wrongExplanations":{"0":"URL; İnternet üzerindeki bir dosyanın veya kaynağın tam konumunu belirten adrestir.","1":"HTML; web belgelerini yapılandırmak için kullanılan etiketleme sözdizimidir.","2":"W3C; Web standartlarını belirlemek amacıyla kurulan uluslararası konsorsiyumdur.","3":"BBS; kullanıcıların modemle bağlandığı erken dönem bülten panosu sistemidir."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 06","metin":"Which term is defined as a \\"document cross-reference technique enabling the retrieval of a related document or resource simply by clicking on an underlined word or image\\"?","secenekler":["Hyperlink","Emoticon","Cookie","Backbone","Baud"],"dogruCevap":0,"explanation":"Doğru cevap Hyperlink (köprü/bağlantı) terimidir. Soru kökündeki \'cross-reference technique\' ve \'clicking on an underlined word or image\' ifadeleri bu tekniğin kesin tanımıdır.","wrongExplanations":{"1":"Emoticon; duygu belirtmek için klavye karakterleriyle oluşturulan simgedir (örneğin `:)`).","2":"Cookie; web siteleri tarafından kullanıcının bilgisayarında saklanan kişisel bilgi içeren metin dosyasıdır.","3":"Backbone; bağımsız alt ağları birbirine bağlayan merkezi yüksek hızlı omurga ağıdır.","4":"Baud; erken dönem modemlerde veri aktarım ve sembol hızını niteleyen birimdir."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 07","metin":"Which technical specification is officially defined as \\"the coding or tagging syntax used to write documents for web browsers\\"?","secenekler":["Uniform Resource Locator (URL)","Hypertext Markup Language (HTML)","Bulletin Board System (BBS)","Advanced Research Projects Agency Network (ARPANET)","World Wide Web Consortium (W3C)"],"dogruCevap":1,"explanation":"Doğru cevap HTML terimidir. Soru kökündeki \'coding or tagging syntax\' (kodlama veya etiketleme sözdizimi) ve \'write documents for web browsers\' ifadeleri doğrudan HTML dilini tanımlar.","wrongExplanations":{"0":"URL; bir dosyanın internet üzerindeki konumunu belirten adrestir, kodlama sözdizimi değildir.","2":"BBS; modemle erişilen erken dönem çevrimiçi topluluk sistemidir.","3":"ARPANET; paket anahtarlama tabanlı ilk askeri omurga ağıdır.","4":"W3C; Web standartlarını belirleyen organizasyondur, bir kodlama sözdizimi değildir."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 08","metin":"Which core infrastructure element is defined as \\"a central high speed network that connects smaller, independent networks\\"?","secenekler":["Dial-up Modem","Bulletin Board System (BBS)","Backbone","Web Browser","Packet Switch"],"dogruCevap":2,"explanation":"Doğru cevap Backbone (omurga) terimidir. Soru kökündeki \'central high speed network\' ve \'connects smaller, independent networks\' ifadeleri omurga ağ yapısının resmî tanımıdır.","wrongExplanations":{"0":"Dial-up Modem; analog telefon hatları üzerinden dijital veri iletimi sağlayan yavaş bir bağlantı cihazıdır.","1":"BBS; kullanıcıların çevirmeli ağ ile bağlandığı bülten panosu platformudur.","3":"Web Browser; web sayfalarını görüntülemek ve düzenlemek için kullanılan yazılımdır.","4":"Packet Switch; veri paketlerini ağ üzerinde yönlendiren ara donanım/teknolojidir."},"vurgulu":false},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 09","metin":"Which early online architecture is described as \\"a predecessor to modern websites, these were early online communities that users could dial into using a modem\\"?","secenekler":["Uniform Resource Locator (URL)","World Wide Web Consortium (W3C)","Hypertext Markup Language (HTML)","Bulletin Board System (BBS)","Broadband Network System (BNS)"],"dogruCevap":3,"explanation":"Doğru cevap BBS (Bulletin Board System) terimidir. Soru kökündeki \'predecessor to modern websites\' ve \'dial into using a modem\' ifadeleri BBS topluluklarının anahtar özellikleridir.","wrongExplanations":{"0":"URL; web üzerindeki dosyaların konumunu gösteren adrestir.","1":"W3C; Web standartlarını geliştiren resmi kuruluştur.","2":"HTML; web tarayıcıları için doküman hazırlama etiket dilidir.","4":"BNS; metinde geçen teknik bir terim veya erken dönem topluluk modeli değildir."},"vurgulu":false},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 10","metin":"Which data entity is technically defined as \\"a text file created by web sites which contains personal information about an end user\\"?","secenekler":["Emoticon","Hyperlink","Hypertext","Backbone","Cookie"],"dogruCevap":4,"explanation":"Doğru cevap Cookie (çerez) terimidir. Soru kökündeki \'text file created by web sites\' ve \'contains personal information about an end user\' ifadeleri çerez kavramını işaret eden tetikleyicilerdir.","wrongExplanations":{"0":"Emoticon; duygu aktarımı için klavye karakterleriyle yazılan sembollerdir.","1":"Hyperlink; belgelere geçişi sağlayan tıklanabilir bağlantıdır.","2":"Hypertext; elektronik çapraz referanslı doküman yapısıdır.","3":"Backbone; bağımsız ağları birbirine bağlayan merkezi ana iletişim hattıdır."},"vurgulu":false},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 11","metin":"Which networking identifier is formally defined as \\"the unique name which identifies a web site\\"?","secenekler":["Domain Name","Emoticon","Backbone","Cookie","Baud"],"dogruCevap":0,"explanation":"Doğru cevap Domain Name (alan adı) terimidir. Soru kökündeki \'unique name\' ve \'identifies a web site\' ifadeleri doğrudan alan adının tanımını oluşturur.","wrongExplanations":{"1":"Emoticon; duyguları ifade etmek amacıyla kullanılan klavye karakter kombinasyonudur.","2":"Backbone; küçük ağları bağlayan yüksek hızlı ana omurga şebekesidir.","3":"Cookie; web sitelerinin kullanıcı hakkında bilgi tuttuğu metin dosyasıdır.","4":"Baud; modemin veri iletim hızını gösteren sembol ölçü birimidir."},"vurgulu":false},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 12","metin":"Which business sector is officially defined as \\"the term for buying and selling goods and services over the world wide web\\"?","secenekler":["Packet Switching Network","Electronic Commerce (E-commerce)","Bulletin Board System (BBS)","Digital Media Streaming","Online Search Optimization"],"dogruCevap":1,"explanation":"Doğru cevap E-commerce (Elektronik Ticaret) terimidir. Web üzerinden mal ve hizmetlerin alınıp satılması (\'buying and selling goods and services over the world wide web\') doğrudan e-ticaret olarak tanımlanır.","wrongExplanations":{"0":"Packet Switching Network; verinin paketler halinde hedefe iletilmesini sağlayan ağ teknolojisidir.","2":"BBS; modemle erişilen ilkel bülten panosu sistemidir, ticari satış katmanı değildir.","3":"Digital Media Streaming; ses ve video verilerinin anlık olarak oynatılması teknolojisidir.","4":"Online Search Optimization; arama motorlarında bulunabilirliği artırma yöntemidir."},"vurgulu":false},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 13","metin":"Which digital element is defined as \\"a symbol that uses the characters on a computer keyboard to convey emotion in an email or instant message, such as the smiley face :)\\"?","secenekler":["Domain Name","Hypertext","Emoticon","Cookie","Bookmark"],"dogruCevap":2,"explanation":"Doğru cevap Emoticon (duygu ifadesi simgesi) terimidir. Klavyedeki karakterleri kullanarak duygu aktarmayı sağlayan simgeler (\'characters on a computer keyboard to convey emotion\') emoticon olarak adlandırılır.","wrongExplanations":{"0":"Domain Name; bir web sitesini niteleyen benzersiz adrestir.","1":"Hypertext; çapraz referanslı metin dokümanı biçimidir.","3":"Cookie; web sitelerinin kullanıcıyı tanımak için oluşturduğu metin dosyasıdır.","4":"Bookmark; tarayıcıda sık kullanılan web sitelerini saklayan yer imidir."},"vurgulu":false},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 14","metin":"Which addressing concept represents \\"the address which specifies the location of a file on the Internet\\"?","secenekler":["Hypertext Markup Language (HTML)","World Wide Web Consortium (W3C)","Bulletin Board System (BBS)","Uniform Resource Locator (URL)","Advanced Research Projects Agency (ARPA)"],"dogruCevap":3,"explanation":"Doğru cevap URL (Uniform Resource Locator) terimidir. Soru kökündeki \'address which specifies the location of a file on the Internet\' ifadesi URL kavramının kesin tanımıdır.","wrongExplanations":{"0":"HTML; web sayfalarının yapısını oluşturan işaretleme sözdizimidir.","1":"W3C; Web standartlarını belirleyen otorite kuruluştur.","2":"BBS; modemle bağlanılan erken dönem çevrimiçi topluluk yapısıdır.","4":"ARPA; ARPANET ağını inşa eden ABD Savunma Bakanlığı araştırma ajansıdır."},"vurgulu":false},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 15","metin":"Which international entity is defined as \\"an organization which develops specifications and guidelines for the World Wide Web\\" to lead it to its full potential?","secenekler":["Advanced Research Projects Agency (ARPA)","French Telecommunications Ministry (Minitel)","Bulletin Board Systems Association (BBSA)","Commercial Internet Exchange (CIX)","World Wide Web Consortium (W3C)"],"dogruCevap":4,"explanation":"Doğru cevap W3C (World Wide Web Consortium) seçeneğidir. 1994 yılında kurulan W3C; \'develops specifications and guidelines for the World Wide Web\' misyonunu üstlenmiş standart kuruluşudur.","wrongExplanations":{"0":"ARPA; 1960\'larda askeri iletişim için ARPANET\'i finanse edip kuran kuruluştur.","1":"Minitel; Fransa\'ya özgü kalan erken dönem bağımsız bir terminal ağıdır.","2":"BBSA; standart belirleyici küresel bir konsorsiyum değildir.","3":"CIX; erken dönem ISP\'lerin veri değişim noktasıdır, web içerik standartlarını belirlemez."},"vurgulu":false},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 16","metin":"Which pioneer invented the \\"packet-switching technology\\" that made the ARPANET network robust against failure and eliminated any single point of failure?","secenekler":["Lawrence Roberts","Tim Berners-Lee","Vannevar Bush","Bill Gates","Steve Jobs"],"dogruCevap":0,"explanation":"Doğru cevap Lawrence Roberts\'tır. ARPANET\'i başarılı kılan ve nükleer bir savaşta tek bir arıza noktası olmaksızın (no single point of failure) bilginin iletilmesini sağlayan paket anahtarlama (packet-switching) teknolojisi Lawrence Roberts tarafından icat edilmiştir.","wrongExplanations":{"1":"Tim Berners-Lee; 1990 yılında World Wide Web\'i icat eden ve 1994\'te W3C\'yi kuran bilim insanıdır.","2":"Vannevar Bush; 1945 yılında Hypertext (köprü metin) kavramını kuramsallaştıran düşünürdür.","3":"Bill Gates; Microsoft şirketinin kurucusudur, paket anahtarlamanın mucidi değildir.","4":"Steve Jobs; Apple şirketinin kurucu ortağıdır, ARPANET teknolojileriyle doğrudan bağı yoktur."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 17","metin":"In 1990, which scientist introduced an exciting hypertext and multimedia layer to the Internet, thereby creating the \\"World Wide Web\\"?","secenekler":["Lawrence Roberts","Tim Berners-Lee","Vannevar Bush","Marc Andreessen","Robert Kahn"],"dogruCevap":1,"explanation":"Doğru cevap Tim Berners-Lee\'dir. 1990 yılında İnternet üzerine köprü metin ve multimedya katmanı ekleyerek World Wide Web\'i icat etmiş, ardından 1994\'te W3C\'yi kurmuştur.","wrongExplanations":{"0":"Lawrence Roberts; paket anahtarlama teknolojisini geliştirip ARPANET\'i tasarlayan mühendistir.","2":"Vannevar Bush; 1945 yılında hipermetin fikrini ilk kez öngören teorisyendir.","3":"Marc Andreessen; erken dönem Mosaic ve Netscape web tarayıcılarını geliştiren yazılımcıdır.","4":"Robert Kahn; TCP/IP protokolünün ortak mucitlerinden biridir."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 18","metin":"What were the two primary reasons that triggered the first financial crash of the Internet in 1999, known as the \\"Dot-Com Bubble\\"?","secenekler":["High server hardware costs and heavy government taxation","Strict international censorship and universal broadband bans","Slow connection speeds and excessive commercial optimism","Rapid decline in computer ownership and browser obsolescence","Universal migration to text-only Bulletin Board Systems (BBS)"],"dogruCevap":2,"explanation":"Doğru cevap yavaş bağlantı hızları ve aşırı iyimserliktir (slow connection speeds and too much optimism). 1999 yılındaki Dot-Com Balonu çöküşünün en önemli iki tetikleyicisi bu faktörlerdir.","wrongExplanations":{"0":"Sunucu donanım maliyetleri veya hükümet vergileri krizin temel sebepleri arasında sayılmamıştır.","1":"Uluslararası sansür veya geniş bant yasakları bu dönemdeki krizin kaynağı değildir.","3":"Bilgisayar sahipliğinde azalma yaşanmamış, aksine bilgisayarlar ev ve ofislerde hızla yaygınlaşmıştır.","4":"BBS sistemlerine geri dönüş yaşanmamış, krizin ardından Web 2.0 mimarisi doğmuştur."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 19","metin":"Which technological evolution accurately defines the transition from \\"Web 1.0\\" to \\"Web 2.0\\" following the Dot-Com Bubble?","secenekler":["Transition from high-speed fiber back to dial-up acoustic couplers","Transition from dynamic interactive wikis to static text catalogs","Transition from universal online commerce to isolated mainframes","Transition from slow, static pages to faster, more dynamic sites","Transition from graphical interfaces to monochrome command lines"],"dogruCevap":3,"explanation":"Doğru cevap dördüncü seçenektir. Web 1.0; yavaş, statik ve kullanışsız (slow, static, and unusable) bir deneyim iken; Web 2.0 ortalama bir kullanıcı için daha hızlı, dinamik ve etkileşimli (faster, more dynamic, and more usable) ikinci bir web evresini temsil eder.","wrongExplanations":{"0":"Geniş banttan çevirmeli ağa geri dönüş olmamış; tam tersine broadband modemler video akışını mümkün kılmıştır.","1":"Statik kataloglardan dinamik vikilere geçiş yaşanmıştır, sürecin yönü ters verilmiştir.","2":"E-ticaretten izole ana bilgisayarlara değil, sosyal medya ve küresel platformlara geçilmiştir.","4":"Web 2.0 ile birlikte zengin grafikli, gelişmiş arayüzler ve sosyal medya siteleri öne çıkmıştır."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 20","metin":"Which software application category allows people to \\"search, view, and even add and edit data on the World Wide Web\\"?","secenekler":["Operating System Kernel","Network Interface Card (NIC)","Dial-up Modem Driver","Packet Switch Router","Web Browser"],"dogruCevap":4,"explanation":"Doğru cevap Web Browser (web tarayıcısı) terimidir. Chrome, Firefox ve Safari gibi yazılımlar; kullanıcıların Web üzerinde arama yapmasını, içerikleri görüntülemesini ve veri ekleyip düzenlemesini sağlayan istemci uygulamalarıdır.","wrongExplanations":{"0":"Kernel; işletim sisteminin en alt katmanında donanım yönetimini sağlayan çekirdektir, web içeriği görüntülemez.","1":"NIC; bilgisayarı fiziksel ağ ortamına bağlayan donanım arabirimidir.","2":"Dial-up Modem Driver; modemin işletim sistemiyle haberleşmesini sağlayan aygıt sürücüsüdür.","3":"Packet Switch Router; veri paketlerini ağlar arasında yönlendiren ağ donanımıdır."},"vurgulu":false}]'))},79401,e=>{e.v([])},18600,e=>{e.v([])},52461,e=>{e.v([])},60581,e=>{e.v([])},77130,e=>{e.v([])},15210,e=>{e.v([])},37068,e=>{e.v([])},19461,e=>{e.v(JSON.parse('[{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 01","metin":"Which of the following terms is officially defined as an \\"external computer add-on, such as a printer or a scanner; also known as an accessory\\"?","secenekler":["component","peripheral","software","database","network"],"dogruCevap":1,"explanation":"Doğru cevap peripheral (çevre birimi) terimidir. Soru kökündeki \'external computer add-on\' (harici bilgisayar eklentisi) ve \'accessory\' (aksesuar) ifadeleri doğrudan çevre birimlerini niteleyen anahtar kelimelerdir.","wrongExplanations":{"0":"Component (bileşen); anakart veya dahili sabit disk gibi bilgisayar kasasının içinde (internal) yer alan donanımlardır.","2":"Software (yazılım); bilgisayarda çalışmak üzere tasarlanmış kod ve yönergeler bütünüdür, fiziksel donanım eklentisi değildir.","3":"Database (veritabanı); satır, sütun ve anahtarlardan oluşan düzenli elektronik veri koleksiyonudur.","4":"Network (ağ); kaynak paylaşımı amacıyla birbirine bağlanmış bilgisayarlar grubudur."},"vurgulu":true},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 02","metin":"The technical term that literally means \\"that which is given\\", referring to \\"raw information of any kind\\", is formally known as:","secenekler":["data","code","file","byte","link"],"dogruCevap":0,"explanation":"Doğru cevap data (veri) terimidir. Soru kökünde belirtilen \'that which is given\' (verilen şey) ifadesi ve işlenmemiş ham bilgiyi tanımlayan \'raw information of any kind\' kalıbı doğrudan data kavramını işaret eder.","wrongExplanations":{"1":"Code; bir programlama dilinde yazılmış yönergeler ve kaynak metinlerdir.","2":"File; depolama birimlerinde belirli bir isim altında saklanan veri veya program bloğudur.","3":"Byte; 8 bitten oluşan standart dijital veri depolama ve bellek birimidir.","4":"Link; belgeler veya kaynaklar arasında geçiş sağlayan bağlantıdır."},"vurgulu":false},{"hafta":1,"kategori":"Unit 1: Information Technology 101","baslik":"Soru 03","metin":"An \\"organized, electronic collection of information optimized for fast access and typically consisting of rows, columns, indexes, and keys\\" is technically defined as a:","secenekler":["spreadsheet","repository","database","hyperlink","filesystem"],"dogruCevap":2,"explanation":"Doğru cevap database (veritabanı) terimidir. Soru kökündeki \'organized electronic collection\', \'optimized for fast access\' ve \'rows, columns, indexes, and keys\' ifadeleri veritabanının kesin ayırt edici özellikleridir.","wrongExplanations":{"0":"Spreadsheet; hesap tabloları oluşturan kullanıcı uygulamasıdır (Excel vb.), teknik veritabanı altyapısı değildir.","1":"Repository; yazılım paketlerinin ve kaynak kod depolarının saklandığı arşiv alanıdır.","3":"Hyperlink; dokümanlar arasında geçiş sağlayan köprü bağlantı tekniğidir.","4":"Filesystem; işletim sisteminin disk üzerindeki dosyaları takip etme ve organize etme yöntemidir."},"vurgulu":false},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 04","metin":"In software terminology, which of the following terms is formally defined strictly as \\"an error in a computer program\\"?","secenekler":["crash","error","abort","bug","patch"],"dogruCevap":3,"explanation":"Doğru cevap bug (yazılım hatası) terimidir. Ders notlarına göre bir bilgisayar programının içindeki mantıksal veya teknik kusuru doğrudan karşılayan resmî tanım \'an error in a computer program\' ifadesidir.","wrongExplanations":{"0":"Crash; donanım arızası veya ciddi bir bug yüzünden sistemin/bilgisayarın tamamen durmasıdır (computer failure).","1":"Error; bilgisizlik veya dikkatsizlik sonucu insan kaynaklı hatalı eylemdir (incorrect action attributable to poor judgment).","2":"Abort; bir süreci veya programı tamamlanmadan önce zorla durdurmaktır (to end before completion).","4":"Patch; yazılımdaki hataları veya açıkları kapatmak için sunulan güncellemedir."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 05","metin":"When a computer program stops responding and a user is forced to \\"end a program or a process before its completion\\", this action is called to:","secenekler":["execute","compile","suspend","restart","abort"],"dogruCevap":4,"explanation":"Doğru cevap abort (zorla sonlandırmak/iptal etmek) fiilidir. Soru kökündeki \'to end a program or a process before its completion\' kalıbı sürecin normal bitişi beklenmeden durdurulmasını ifade eder.","wrongExplanations":{"0":"Execute; programı başlatmak ve çalıştırmaktır (to start a program).","1":"Compile; kaynak kodu makinenin anlayacağı ikili (binary) koda dönüştürmektir.","2":"Suspend; işlemi tamamen sonlandırmak yerine geçici olarak askıya almaktır.","3":"Restart; sistemi veya uygulamayı kapatıp yeniden başlatmaktır."},"vurgulu":true},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 06","metin":"What is considered the \\"most correct technical term\\" when referring to the action \\"to start a program on a computer\\"?","secenekler":["launch","execute","install","trigger","process"],"dogruCevap":1,"explanation":"Doğru cevap execute fiilidir. Okuma metninde \'to start a program on a computer\' eylemini teknik bağlamda en resmî ve doğru ifade eden fiilin execute olduğu açıkça belirtilmiştir.","wrongExplanations":{"0":"Launch; günlük kullanımda yaygın olan fakat metinde en teknik terim olarak gösterilmeyen alternatiftir.","2":"Install; programı çalıştırmak değil, diske ve sisteme ilk kurulumunu yapmaktır.","3":"Trigger; bir olayı veya prosedürü tetiklemek anlamına gelir.","4":"Process; veriyi işlemek veya arka plan işlemi anlamına gelir."},"vurgulu":false},{"hafta":2,"kategori":"Unit 2: Introduction to Software","baslik":"Soru 07","metin":"A software program where the license strictly stipulates that \\"the user cannot see, edit, or manipulate the source code\\" is categorized as:","secenekler":["closed source","freeware","open source","firmware","shareware"],"dogruCevap":0,"explanation":"Doğru cevap closed source (kapalı kaynak) yazılımdır. \'License stipulates that the user cannot see, edit, or manipulate the source code\' ifadesi doğrudan kapalı kaynak modelini tanımlar.","wrongExplanations":{"1":"Freeware; tamamen ücretsiz dağıtılan yazılımdır, odak noktası kaynak kodun gizliliği değil fiyatsız olmasıdır.","2":"Open source; kaynak kodu herkese açık olan ve serbestçe değiştirilebilen yazılımdır.","3":"Firmware; donanım çiplerinin içine kalıcı olarak yazılmış mikro yazılımdır.","4":"Shareware; kullanım süresi veya özelliği kısıtlı deneme sürümlü yazılımdır."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 08","metin":"Which software layer is \\"the fundamental core of an operating system responsible for hardware access\\", situated above the lower-level software that \\"isn\'t actually a part of the OS\\"?","secenekler":["device driver","system BIOS","shell script","kernel","hypervisor"],"dogruCevap":3,"explanation":"Doğru cevap kernel (çekirdek) terimidir. Kernel, işletim sisteminin kalbi (core/lowest level of the OS) olup donanıma erişim sağlar; BIOS ise kernel\'dan alttadır ancak işletim sisteminin bir parçası değildir.","wrongExplanations":{"0":"Device driver; donanım ile işletim sistemi arasındaki veri formatını dönüştüren sürücüdür.","1":"System BIOS; donanımı başlatan en alt düzey yazılımdır ancak metinde işletim sisteminin bir parçası olmadığı özellikle vurgulanmıştır.","2":"Shell script; komut satırı arayüzünde çalışan betik dosyalarıdır.","4":"Hypervisor; sanal makineleri yöneten sanallaştırma katmanıdır."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 09","metin":"A user interface that provides \\"a text-only link between a computer and its operator\\", commonly utilized by system administrators, is known as a:","secenekler":["graphical user interface","virtual desktop console","command line interface","system control panel","network socket manager"],"dogruCevap":2,"explanation":"Doğru cevap command line interface (CLI) seçeneğidir. \'A text-only link between a computer and its operator\' tanımı doğrudan metin tabanlı komut satırı arayüzünü ifade eder.","wrongExplanations":{"0":"Graphical user interface (GUI); simgelere ve pencerelere dayanan görsel bağlantıdır (icon-based link).","1":"Virtual desktop console; uzak masaüstü bağlantı aracıdır.","3":"System control panel; işletim sistemi ayarlarının yapıldığı görsel paneldir.","4":"Network socket manager; ağ soketlerini denetleyen iletişim arabirimidir."},"vurgulu":true},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 10","metin":"Which of the following is defined as \\"software which converts the data from a component or peripheral into data that an operating system can use\\"?","secenekler":["virtual machine","system kernel","network socket","binary compiler","device driver"],"dogruCevap":4,"explanation":"Doğru cevap device driver (aygıt sürücüsü) terimidir. Donanım bileşeni veya çevre biriminden gelen verileri işletim sisteminin anlayacağı forma dönüştüren yazılımdır (\'converts data from a component or peripheral into data that an OS can use\').","wrongExplanations":{"0":"Virtual machine; donanımı taklit ederek bağımsız işletim sistemi çalıştıran yazılımdır.","1":"System kernel; işletim sisteminin temel çekirdeğidir.","2":"Network socket; ağ üzerinden veri alışverişi için kullanılan yazılımsal uç noktadır.","3":"Binary compiler; kaynak kodları makine koduna dönüştüren derleyicidir."},"vurgulu":false},{"hafta":3,"kategori":"Unit 3: Learning About Operating Systems","baslik":"Soru 11","metin":"A software program which \\"mimics the performance of one or more hardware devices in order to run software independently of the actual hardware\\" is called a:","secenekler":["virtual machine","operating system","device driver","compiler unit","cloud storage"],"dogruCevap":0,"explanation":"Doğru cevap virtual machine (sanal makine - VM) seçeneğidir. \'Mimics the performance of one or more hardware devices\' kalıbı doğrudan sanal makinelerin resmi teknik tanımıdır.","wrongExplanations":{"1":"Operating system; üretkenlik yazılımlarına altyapı sağlayan temel çok görevli katmandır.","2":"Device driver; donanım verilerini işletim sistemine aktaran köprü yazılımdır.","3":"Compiler unit; programlama dillerini ikili koda dönüştüren derleme birimidir.","4":"Cloud storage; verilerin internet üzerindeki uzak sunucularda saklanmasıdır."},"vurgulu":false},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Applications","baslik":"Soru 12","metin":"Which stage of software development represents \\"normally the first version of an application that is feature-ready, released to internal testers, and contains known bugs\\"?","secenekler":["release candidate","beta version","alpha version","final release","patch build"],"dogruCevap":2,"explanation":"Doğru cevap alpha version (alfa sürümü) terimidir. \'First version\', \'feature-ready\', \'released to testers\' ve \'contains known bugs / proof of concept\' ifadeleri alfa sürümünün belirleyici tetikleyicileridir.","wrongExplanations":{"0":"Release candidate; beta testlerini başarıyla geçmiş ve nihai yayına neredeyse hazır olan sürümdür.","1":"Beta version; halka açık test ve geri bildirim amacıyla dağıtılan sürümdür.","3":"Final release; mağazalardan satın alınan veya indirilen gerçek nihai üründür.","4":"Patch build; çıkmış bir sürümdeki hataları onarmak için hazırlanan yama paketidir."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Applications","baslik":"Soru 13","metin":"A software version distributed across the Internet for \\"testing purposes before it is released to the public, in order to get free, real-world feedback\\" is a:","secenekler":["alpha release","beta version","shareware build","golden master","retail package"],"dogruCevap":1,"explanation":"Doğru cevap beta version (beta sürümü) terimidir. \'Testing purposes before released to the public\' ve \'real-world testing and feedback\' ifadeleri beta sürümünü net biçimde tanımlar.","wrongExplanations":{"0":"Alpha release; halka kapalı olan, kurum içi testçilere sunulan kavram kanıtı aşamasıdır.","2":"Shareware build; süre veya işlevsellik kısıtlamalı ticari deneme yazılımıdır.","3":"Golden master; Apple terminolojisinde sürüm adayına (Release Candidate) verilen addır.","4":"Retail package; mağazalarda kutulu satılan nihai kullanıcı sürümüdür."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Applications","baslik":"Soru 14","metin":"A build that has \\"passed the beta testing stage and is almost ready to be released to the public as a feature-complete product\\" (internally called \'the golden master\' by Apple) is the:","secenekler":["alpha prototype","public beta","security patch","release candidate","commercial demo"],"dogruCevap":3,"explanation":"Doğru cevap release candidate (RC - yayın adayı) seçeneğidir. \'Passed the beta testing stage\', \'almost ready to be released\', \'feature-complete\' ve Apple\'ın kullandığı \'the golden master\' terimi doğrudan RC\'yi ifade eder.","wrongExplanations":{"0":"Alpha prototype; geliştirmenin en başındaki kararsız ilk prototiptir.","1":"Public beta; geniş kitlelerin kullanımına ve geri bildirimine açılmış test sürümüdür.","2":"Security patch; yazılımdaki güvenlik açıklarını kapatan yamadır.","4":"Commercial demo; pazarlama amacıyla hazırlanan kısıtlı tanıtım sürümüdür."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Applications","baslik":"Soru 15","metin":"Proprietary software that can be distributed freely across the Internet, but is \\"limited by features and/or a time limit until a full version is purchased\\", is called:","secenekler":["open source","freeware","firmware","malware","shareware"],"dogruCevap":4,"explanation":"Doğru cevap shareware terimidir. Serbestçe dağıtılabilen ancak tam sürümü satın alınıncaya kadar süre (örn. 30 günlük deneme) veya özellik bakımından kısıtlı olan yazılım modelidir.","wrongExplanations":{"0":"Open source; kaynak kodları açık ve tamamen serbestçe değiştirilebilen yazılımdır.","1":"Freeware; geliştiricisi tarafından tamamen ücretsiz sunulan, süre veya özellik kısıtlaması olmayan kapalı kaynaklı yazılımdır.","2":"Firmware; donanım çiplerinde gömülü bulunan yazılımdır.","3":"Malware; sistemlere zarar vermek amacıyla yazılmış kötü amaçlı yazılımdır."},"vurgulu":true},{"hafta":4,"kategori":"Unit 4: The Software Development Cycle & Applications","baslik":"Soru 16","metin":"Due to programming complexity, bugs may persist in final releases. A software update specifically designed to \\"fix bugs or security holes\\" is a:","secenekler":["patch","build","kernel","backup","driver"],"dogruCevap":0,"explanation":"Doğru cevap patch (yama) terimidir. \'A software update intended to fix bugs or security holes\' ifadesi doğrudan yama tanımıdır.","wrongExplanations":{"1":"Build; kaynak kodların derlenmesiyle oluşturulan yazılım sürüm derlemesidir.","2":"Kernel; işletim sisteminin donanımı yöneten merkezi çekirdeğidir.","3":"Backup; veri kaybını önlemek için alınan veri yedeğidir.","4":"Driver; donanım aygıtları ile işletim sistemini konuşturan sürücüdür."},"vurgulu":false},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 17","metin":"Which executive job position is responsible for \\"internal processes, IT budgets, and staff outsourcing\\", typically possessing a stronger business background than technical background?","secenekler":["Chief Technical Officer (CTO)","Chief Information Officer (CIO)","Enterprise Architect","Network Administrator","Database Administrator (DBA)"],"dogruCevap":1,"explanation":"Doğru cevap Chief Information Officer (CIO) unvanıdır. CIO iç süreçlerden (internal processes), BT bütçesinden ve dış kaynak yönetiminden sorumludur; yönetim/işletme arka planı teknik yönünden daha baskındır.","wrongExplanations":{"0":"Chief Technical Officer (CTO); tüm bilimsel ve teknolojik meselelerden sorumlu, teknik yönü yönetim yönünden daha güçlü olan üst düzey yöneticidir.","2":"Enterprise Architect; kurumsal ihtiyaçlara uygun genel BT mimarisini tasarlayan uzmandır.","3":"Network Administrator; ağ altyapısının kesintisiz çalışmasından ve yönlendirmeden sorumlu uzmandır.","4":"Database Administrator (DBA); ilişkisel veritabanlarının bakımından ve erişim haklarından sorumlu kişidir."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 18","metin":"A professional whose role is defined as \\"acting as a bridge between upper management and IT staff; one who encourages personal development and acts as the boss of an IT worker\\" is the:","secenekler":["Project Manager (PM)","Scrum Master","IT Manager","QA Manager","Lead Developer"],"dogruCevap":2,"explanation":"Doğru cevap IT Manager pozisyonudur. Soru kökündeki \'bridge between upper management and IT staff\' ve \'the boss of an IT worker\' ifadeleri doğrudan BT Yöneticisini işaret eder.","wrongExplanations":{"0":"Project Manager (PM); üst yönetimle değil, \'developers and stake-holders\' arasında köprü vazifesi gören ve projeyi bütçesinde teslim eden yöneticidir.","1":"Scrum Master; çevik yazılım geliştirme süreçlerini kolaylaştıran rehber roldür.","3":"QA Manager; test ekibini organize eden ve yazılım kalite standartlarını denetleyen yöneticidir.","4":"Lead Developer; yazılım ekibine teknik liderlik ve mimari rehberlik yapan kıdemli geliştiricidir."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 19","metin":"A specialist in charge of \\"managing and maintaining relational databases and their access rights, as well as handling disaster recovery\\" is a:","secenekler":["Database Administrator (DBA)","Database Developer","Systems Architect","Network Engineer","Software Tester"],"dogruCevap":0,"explanation":"Doğru cevap Database Administrator (DBA) pozisyonudur. İlişkisel veritabanlarını yönetme, koruma, felaket kurtarma ve özellikle kullanıcı erişim haklarını (access rights) denetleme DBA\'nın sorumluluğundadır.","wrongExplanations":{"1":"Database Developer; veritabanını programlayan, tabloları normalleştiren (3NF) ve optimize eden uzmandır.","2":"Systems Architect; büyük ölçekli kurumsal bilişim sistemlerinin altyapısını tasarlar.","3":"Network Engineer; kurumsal ağ topolojilerini kurar ve yönlendiricileri yapılandırır.","4":"Software Tester; yazılımdaki hataları bulup belgeleyen test uzmanıdır."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 20","metin":"A position responsible for \\"making complex data structures easy to understand and navigate\\", typically preparing wireframes at the start of a project, is an:","secenekler":["Graphic Designer","Technical Writer","Software Developer","Business Analyst (BA)","Information Architect"],"dogruCevap":4,"explanation":"Doğru cevap Information Architect (Bilgi Mimarı) unvanıdır. \'Making complex data structures easy to understand and navigate\' ve proje başında \'wireframes\' (tel kafes) hazırlama görevi doğrudan Bilgi Mimarına aittir.","wrongExplanations":{"0":"Graphic Designer; ön yüz sistemleri için görsel, tipografi ve mock-up tasarlayan uzmandır.","1":"Technical Writer; kullanım kılavuzları, yardım belgeleri ve teknik şartnameleri yazan kişidir.","2":"Software Developer; programlama görevlerini yerine getiren yazılımcıdır.","3":"Business Analyst (BA); iş kurallarını analiz ederek teknik sistemlere aktaran analisttir."},"vurgulu":true},{"hafta":5,"kategori":"Unit 5: Choosing an IT Career Path","baslik":"Soru 21","metin":"Which IT role is defined as being responsible for \\"setting best practices for securing Wi-Fi networks, servers, backups, laptops, and VPNs\\"?","secenekler":["Network Administrator","System Administrator","IT Support Engineer","IT Security Manager","Enterprise Architect"],"dogruCevap":3,"explanation":"Doğru cevap IT Security Manager (BT Güvenlik Yöneticisi) rolüdür. \'Securing Wi-Fi networks, servers, backups, laptops, and VPNs\' ifadesi doğrudan BT güvenlik yöneticisinin görev tanımıdır.","wrongExplanations":{"0":"Network Administrator; ağ omurgasının genel bakımından ve TCP/IP yönlendirmelerinden sorumludur.","1":"System Administrator; sunucu sistemlerinin genel yönetiminden ve kullanıcı hesaplarından sorumludur.","2":"IT Support Engineer; son kullanıcılara donanım, yazılım ve temel ağ sorunlarında anlık destek sunar.","4":"Enterprise Architect; genel iş gereksinimlerine uygun kurumsal BT omurgasını tasarlar."},"vurgulu":false},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 22","metin":"What is formally defined as \\"a global hypertext system operating on the Internet that enables electronic communication of text and multimedia\\"?","secenekler":["broadband network","ARPANET infrastructure","World Wide Web (WWW)","domain name system","bulletin board system"],"dogruCevap":2,"explanation":"Doğru cevap World Wide Web (WWW) seçeneğidir. İnternet fiziksel ağ altyapısı iken; onun üzerinde çalışan köprü metin ve multimedya katmanı World Wide Web\'dir (\'an application that runs on the Internet\').","wrongExplanations":{"0":"Broadband network; yüksek hızlı fiziksel geniş bant internet bağlantısıdır.","1":"ARPANET infrastructure; 1960\'larda nükleer savaşa dayanmak üzere kurulan askeri ağ omurgasıdır.","3":"Domain name system; web sitelerinin IP adreslerini alan adlarıyla eşleştiren sistemdir.","4":"Bulletin board system (BBS); modemle bağlanılan ilk nesil çevrimiçi bülten panolarıdır."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 23","metin":"The technical operation describing \\"the transfer of a file or files from a remote computer to the user\'s computer\\" is known as:","secenekler":["upload","download","browse","stream","packet"],"dogruCevap":1,"explanation":"Doğru cevap download (indirme) terimidir. Dosyanın uzaktaki bir sunucudan kullanıcının yerel bilgisayarına çekilmesi \'from a remote computer to the user\'s computer\' kalıbıyla download olarak tanımlanır.","wrongExplanations":{"0":"Upload; dosyanın yerel bilgisayardan uzak sunucuya aktarılmasıdır (from local to remote).","2":"Browse; web tarayıcısı üzerinde web sayfalarını gezinme eylemidir.","3":"Stream; medya dosyalarını diske kaydetmeden gerçek zamanlı olarak internetten oynatmaktır.","4":"Packet; ağ üzerinden taşınan adresli veri parçasıdır."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 24","metin":"Which critical technology invented by Lawrence Roberts ensured ARPANET had \\"no single point of failure\\" by sending addressed information along any open path?","secenekler":["circuit routing","dial-up channel","broadband link","simplex stream","packet switching"],"dogruCevap":4,"explanation":"Doğru cevap packet switching (paket anahtarlama) teknolojisidir. Lawrence Roberts tarafından icat edilen, bilginin kaynak ve hedef adresli paketlere bölünerek tek bir arıza noktası olmaksızın iletilmesini sağlayan temel teknolojidir.","wrongExplanations":{"0":"Circuit routing; eski telefon hatlarında kullanılan ve tek bir hat kesilince bağlantıyı koparan devre anahtarlamadır.","1":"Dial-up channel; telefon hatları üzerinden çevirmeli ağ ile kurulan yavaş bağlantıdır.","2":"Broadband link; Web 2.0 dönemini başlatan yüksek hızlı geniş bant veri hattıdır.","3":"Simplex stream; verinin yalnızca tek bir yönde akabildiği iletişim kanalıdır."},"vurgulu":true},{"hafta":6,"kategori":"Unit 6: The Rise of the World Wide Web","baslik":"Soru 25","metin":"Which of the following is defined as \\"a text file created by web sites which contains personal information about an end user\\"?","secenekler":["emoticon","hyperlink","bookmark","cookie","domain"],"dogruCevap":3,"explanation":"Doğru cevap cookie (çerez) terimidir. \'A text file created by web sites which contains personal information about an end user\' tanımı doğrudan tarayıcı çerezlerini ifade eder.","wrongExplanations":{"0":"Emoticon; klavye karakterleriyle duygu aktaran simgelerdir (örn. :-)).","1":"Hyperlink; tıklandığında ilgili belgeyi ekrana getiren çapraz referans bağlantısıdır.","2":"Bookmark; kullanıcının web tarayıcısına kaydettiği sık kullanılanlar yer imidir.","4":"Domain; bir web sitesini niteleyen benzersiz alan adıdır (örn. microsoft.com)."},"vurgulu":false}]'))},57453,e=>{e.v([])}]);